-- ======================================================================
-- FILE: 20261020000400_audit_log_and_verification_documents.sql
======================================================================
-- =====================================================================
-- FixLink Ethiopia - 005: audit log and verification documents
-- =====================================================================
-- Verification documents are ID cards, business licences and trade
-- certificates. They are PRIVATE: they live in a private Supabase Storage
-- bucket and are only readable by the owning professional and by
-- administrators. A public professional profile must never expose them.
--
-- Every privileged operation writes an audit_log row. The log is
-- insert-only for application users: nobody may update or delete it.
--
-- The storage buckets and the storage POLICIES live in
-- 20261020001200_storage_and_participant_policies.sql, because they
-- reference job_requests and job_matches, which are created later.
-- =====================================================================

-- ---------------------------------------------------------------------
-- Audit log
-- ---------------------------------------------------------------------
create table if not exists public.audit_log (
  id uuid primary key default extensions.gen_random_uuid(),
  actor_id uuid references public.profiles (id) on delete set null,
  actor_role text not null default 'system',
  action text not null,
  entity_type text not null,
  entity_id uuid,
  -- Non-secret structured context (previous/new status, reasons, ...).
  details jsonb,
  created_at timestamptz not null default now()
);

create index if not exists audit_log_entity_idx on public.audit_log (entity_type, entity_id);
create index if not exists audit_log_created_at_idx on public.audit_log (created_at desc);
create index if not exists audit_log_actor_idx on public.audit_log (actor_id);

comment on table public.audit_log is
  'Append-only administrative audit trail. Insert-only for admins, never updatable.';

alter table public.audit_log enable row level security;

drop policy if exists "audit_log_select_admin" on public.audit_log;
create policy "audit_log_select_admin"
  on public.audit_log
  for select
  to authenticated
  using (public.is_admin());

drop policy if exists "audit_log_insert_admin" on public.audit_log;
create policy "audit_log_insert_admin"
  on public.audit_log
  for insert
  to authenticated
  with check (public.is_admin() and actor_id = public.current_profile_id());

revoke update, delete on public.audit_log from anon, authenticated;
grant select, insert on public.audit_log to authenticated;

-- ---------------------------------------------------------------------
-- Verification documents
-- ---------------------------------------------------------------------
create table if not exists public.verification_documents (
  id uuid primary key default extensions.gen_random_uuid(),
  professional_id uuid not null references public.professionals (id) on delete cascade,
  document_type public.verification_document_type not null,
  -- Private bucket object path, e.g. verification-documents/<proId>/<docId>.pdf
  storage_path text not null,
  original_file_name text not null,
  review_note text,
  reviewed_at timestamptz,
  reviewed_by uuid references public.profiles (id) on delete set null,
  created_at timestamptz not null default now()
);

create index if not exists verification_documents_professional_idx
  on public.verification_documents (professional_id, created_at desc);
create index if not exists verification_documents_pending_idx
  on public.verification_documents (reviewed_at)
  where reviewed_at is null;

alter table public.verification_documents enable row level security;

-- The owner sees their own uploads; administrators see every case.
drop policy if exists "verification_documents_select" on public.verification_documents;
create policy "verification_documents_select"
  on public.verification_documents
  for select
  to authenticated
  using (
    exists (
      select 1 from public.professionals pr
      where pr.id = professional_id
        and (pr.profile_id = public.current_profile_id() or public.is_admin())
    )
  );

drop policy if exists "verification_documents_insert_own" on public.verification_documents;
create policy "verification_documents_insert_own"
  on public.verification_documents
  for insert
  to authenticated
  with check (
    exists (
      select 1 from public.professionals pr
      where pr.id = professional_id and pr.profile_id = public.current_profile_id()
    )
  );

-- Deleting an un-reviewed document is allowed for its owner; reviewed
-- documents are immutable so the audit trail stays meaningful.
drop policy if exists "verification_documents_delete_own" on public.verification_documents;
create policy "verification_documents_delete_own"
  on public.verification_documents
  for delete
  to authenticated
  using (
    reviewed_at is null
    and exists (
      select 1 from public.professionals pr
      where pr.id = professional_id and pr.profile_id = public.current_profile_id()
    )
  );

revoke update on public.verification_documents from anon, authenticated;
grant select, insert, delete on public.verification_documents to authenticated;

-- ---------------------------------------------------------------------
-- Administrator decision on a verification case
-- ---------------------------------------------------------------------
create or replace function public.set_verification_status(
  p_professional_id uuid,
  p_decision public.verification_status,
  p_note text default null
)
returns public.professionals
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor uuid := public.current_profile_id();
  v_professional public.professionals;
  v_previous public.verification_status;
begin
  if not public.is_admin() then
    raise exception 'admin_required' using errcode = '42501';
  end if;

  if p_decision not in ('approved', 'rejected') then
    raise exception 'invalid_decision' using errcode = '22023';
  end if;

  select * into v_professional
  from public.professionals
  where id = p_professional_id
  for update;

  if not found then
    raise exception 'professional_not_found' using errcode = 'P0002';
  end if;

  v_previous := v_professional.verification_status;

  update public.professionals
     set verification_status = p_decision
   where id = p_professional_id
   returning * into v_professional;

  update public.verification_documents
     set reviewed_at = now(),
         reviewed_by = v_actor,
         review_note = nullif(btrim(coalesce(p_note, '')), '')
   where professional_id = p_professional_id
     and reviewed_at is null;

  insert into public.audit_log (actor_id, actor_role, action, entity_type, entity_id, details)
  values (
    v_actor,
    'admin',
    'professional.verification_' || p_decision::text,
    'professional',
    p_professional_id,
    jsonb_build_object('previousStatus', v_previous, 'newStatus', p_decision, 'note', p_note)
  );

  return v_professional;
end;
$$;

comment on function public.set_verification_status(uuid, public.verification_status, text) is
  'Administrator-only verification decision. Writes an audit_log row and stamps the pending documents.';



-- ======================================================================
-- FILE: 20261020000500_notifications_and_push.sql
======================================================================
-- =====================================================================
-- FixLink Ethiopia - 006: notifications, device tokens, push outbox
-- =====================================================================
-- APPLY ORDER: this file must be applied BEFORE the matching and
-- quotation migrations, because they call public.notify().
--
-- Two delivery channels:
--
--  1. In-app notifications (table `notifications`). These are the source
--     of truth. The web app polls / subscribes to them; the mobile app
--     shows them in a list and as a badge.
--
--  2. Mobile push (table `push_outbox`). A row is enqueued for every
--     notification that targets a device, and a Supabase Edge Function
--     drains the outbox and calls Expo's push service.
--
-- Deduplication: `notifications.dedupe_key` is unique per user, so a
-- retried event (webhook replay, edge function retry) never delivers
-- twice. `public.notify()` is the ONLY supported way to create a
-- notification.
-- =====================================================================

create table if not exists public.notifications (
  id uuid primary key default extensions.gen_random_uuid(),
  user_id uuid not null references public.profiles (id) on delete cascade,
  type text not null,
  title text not null,
  body text not null default '',
  -- Deep-link payload. Never contains secrets.
  data jsonb,
  read_at timestamptz,
  dedupe_key text,
  created_at timestamptz not null default now()
);

create unique index if not exists notifications_dedupe_idx
  on public.notifications (user_id, dedupe_key)
  where dedupe_key is not null;
create index if not exists notifications_user_recent_idx
  on public.notifications (user_id, created_at desc);
create index if not exists notifications_unread_idx
  on public.notifications (user_id)
  where read_at is null;

comment on column public.notifications.dedupe_key is
  'Stable key per (user, event). A unique index makes notification delivery idempotent.';

-- ---------------------------------------------------------------------
-- Device tokens for Expo push
-- ---------------------------------------------------------------------
create table if not exists public.device_tokens (
  id uuid primary key default extensions.gen_random_uuid(),
  user_id uuid not null references public.profiles (id) on delete cascade,
  token text not null unique,
  platform public.device_platform not null,
  last_seen_at timestamptz not null default now(),
  created_at timestamptz not null default now()
);

create index if not exists device_tokens_user_idx on public.device_tokens (user_id);

-- ---------------------------------------------------------------------
-- Push outbox (durable background job)
-- ---------------------------------------------------------------------
-- Rows are claimed with `for update skip locked` by the edge function, so
-- two concurrent invocations never send the same push twice.
create table if not exists public.push_outbox (
  id uuid primary key default extensions.gen_random_uuid(),
  user_id uuid not null references public.profiles (id) on delete cascade,
  notification_id uuid references public.notifications (id) on delete cascade,
  title text not null,
  body text not null default '',
  data jsonb,
  status text not null default 'pending' check (status in ('pending', 'sent', 'failed')),
  attempts integer not null default 0,
  last_error text,
  sent_at timestamptz,
  created_at timestamptz not null default now()
);

create index if not exists push_outbox_pending_idx
  on public.push_outbox (created_at)
  where status = 'pending';

-- ---------------------------------------------------------------------
-- The single entry point for creating a notification
-- ---------------------------------------------------------------------
create or replace function public.notify(
  p_user_id uuid,
  p_type text,
  p_title text,
  p_body text default '',
  p_data jsonb default null,
  p_dedupe_key text default null
)
returns public.notifications
language plpgsql
security definer
set search_path = public
as $$
declare
  v_notification public.notifications;
  v_token record;
begin
  if p_user_id is null then
    raise exception 'notification_user_required' using errcode = '22023';
  end if;

  insert into public.notifications (user_id, type, title, body, data, dedupe_key)
  values (p_user_id, p_type, p_title, coalesce(p_body, ''), p_data, p_dedupe_key)
  on conflict (user_id, dedupe_key) where dedupe_key is not null
  do nothing
  returning * into v_notification;

  -- `found` is false when the conflict clause skipped the insert, which
  -- means the notification was already delivered earlier (retry).
  if not found then
    select * into v_notification
    from public.notifications
    where user_id = p_user_id and dedupe_key = p_dedupe_key;
    return v_notification;
  end if;

  -- Enqueue one push per registered device.
  for v_token in
    select dt.id, dt.token
    from public.device_tokens dt
    where dt.user_id = p_user_id
  loop
    insert into public.push_outbox (user_id, notification_id, title, body, data)
    values (p_user_id, v_notification.id, p_notification.title, p_notification.body, p_notification.data);
  end loop;

  return v_notification;
end;
$$;

comment on function public.notify(uuid, text, text, text, jsonb, text) is
  'Create an in-app notification and enqueue device pushes. Idempotent when dedupe_key is supplied.';

-- ---------------------------------------------------------------------
-- Mark notifications as read (owner only)
-- ---------------------------------------------------------------------
create or replace function public.mark_notifications_read(
  p_ids uuid[] default null
)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor uuid := public.current_profile_id();
  v_count integer;
begin
  if v_actor is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;

  if p_ids is null or array_length(p_ids, 1) is null then
    update public.notifications
       set read_at = now()
     where user_id = v_actor and read_at is null;
  else
    update public.notifications
       set read_at = now()
     where user_id = v_actor and read_at is null and id = any (p_ids);
  end if;

  get diagnostics v_count = row_count;
  return v_count;
end;
$$;

-- ---------------------------------------------------------------------
-- Register / refresh a device push token
-- ---------------------------------------------------------------------
create or replace function public.register_device_token(
  p_token text,
  p_platform public.device_platform
)
returns public.device_tokens
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor uuid := public.current_profile_id();
  v_row public.device_tokens;
begin
  if v_actor is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;

  if length(btrim(coalesce(p_token, ''))) < 8 then
    raise exception 'invalid_device_token' using errcode = '22023';
  end if;

  insert into public.device_tokens (user_id, token, platform, last_seen_at)
  values (v_actor, btrim(p_token), p_platform, now())
  on conflict (token) do update
    set user_id = excluded.user_id,
        platform = excluded.platform,
        last_seen_at = now()
  returning * into v_row;

  return v_row;
end;
$$;

-- ---------------------------------------------------------------------
-- Row Level Security
-- ---------------------------------------------------------------------
alter table public.notifications enable row level security;

drop policy if exists "notifications_select_own" on public.notifications;
create policy "notifications_select_own"
  on public.notifications
  for select
  to authenticated
  using (user_id = public.current_profile_id());

-- Writes happen only through public.notify() / public.mark_notifications_read().
revoke insert, update, delete on public.notifications from anon, authenticated;
grant select on public.notifications to authenticated;

alter table public.device_tokens enable row level security;

drop policy if exists "device_tokens_select_own" on public.device_tokens;
create policy "device_tokens_select_own"
  on public.device_tokens
  for select
  to authenticated
  using (user_id = public.current_profile_id());

revoke insert, update, delete on public.device_tokens from anon, authenticated;
grant select on public.device_tokens to authenticated;

alter table public.push_outbox enable row level security;

-- The outbox is written by public.notify() only; the edge function uses
-- the service role, which bypasses RLS.
revoke all on public.push_outbox from anon, authenticated;


-- ======================================================================
-- FILE: 20261020000600_job_requests.sql
======================================================================
-- =====================================================================
-- FixLink Ethiopia - 007: job requests, photos, status events
-- =====================================================================
-- APPLY ORDER: this file comes after 20261020000500_notifications_and_push.sql
-- and before 20261020000700_quotations_and_bookings.sql. It creates the
-- `job_requests` table, which almost every other part of the marketplace
-- refers to.
--
-- A service request moves through: open -> matching -> quoted -> booked
-- -> in_progress -> completed, with cancelled / disputed / expired as
-- the alternative exits.
--
-- The transition matrix lives in `public.job_transition_rules`, seeded
-- from packages/shared-types/src/statuses.ts (JOB_TRANSITIONS). The
-- DATABASE is authoritative: `public.transition_job()` refuses any
-- transition that is not in the table.
-- =====================================================================

do $$
begin
  if not exists (select 1 from pg_type where typname = 'location_source') then
    create type public.location_source as enum ('gps', 'manual');
  end if;
end
$$;

-- The `location_source` enum is kept for the databases that were migrated
-- before the platform moved from GPS coordinates to sub-cities. Nothing
-- writes to it any more: a request is located by its sub-city.

-- ---------------------------------------------------------------------
-- Transition rule matrix (mirrors JOB_TRANSITIONS in shared-types)
-- ---------------------------------------------------------------------
create table if not exists public.job_transition_rules (
  from_status public.job_status not null,
  to_status public.job_status not null,
  actor text not null check (actor in ('customer', 'professional', 'system', 'admin')),
  condition text not null,
  primary key (from_status, to_status, actor)
);

insert into public.job_transition_rules (from_status, to_status, actor, condition)
values
  ('open', 'matching', 'system', 'matching task picked up the request'),
  ('open', 'cancelled', 'customer', 'owner cancels before any quotation is accepted'),
  ('open', 'cancelled', 'admin', 'administrator cancels the request'),
  ('open', 'expired', 'system', 'expired before matching started'),
  ('matching', 'quoted', 'system', 'first eligible quotation submitted'),
  ('matching', 'cancelled', 'customer', 'owner cancels before booking'),
  ('matching', 'cancelled', 'admin', 'administrator cancels the request'),
  ('matching', 'expired', 'system', 'no response within configured timeout windows'),
  ('quoted', 'booked', 'customer', 'owner accepts exactly one valid quotation (atomic)'),
  ('quoted', 'booked', 'system', 'owner accepts exactly one valid quotation (atomic)'),
  ('quoted', 'matching', 'system', 're-queue after all quotations expired'),
  ('quoted', 'cancelled', 'customer', 'owner cancels before booking'),
  ('quoted', 'cancelled', 'admin', 'administrator cancels the request'),
  ('quoted', 'expired', 'system', 'quoting window elapsed without acceptance'),
  ('booked', 'in_progress', 'professional', 'scheduled work begins'),
  ('booked', 'in_progress', 'customer', 'scheduled work begins'),
  ('booked', 'in_progress', 'admin', 'administrator starts the job'),
  ('booked', 'cancelled', 'customer', 'cancellation rules allow it'),
  ('booked', 'cancelled', 'professional', 'cancellation rules allow it'),
  ('booked', 'cancelled', 'admin', 'cancellation rules allow it'),
  ('booked', 'disputed', 'customer', 'problem reported against the booking'),
  ('booked', 'disputed', 'professional', 'problem reported against the booking'),
  ('booked', 'disputed', 'admin', 'problem reported against the booking'),
  ('in_progress', 'completed', 'customer', 'customer confirms completion'),
  ('in_progress', 'completed', 'system', 'customer confirms completion'),
  ('in_progress', 'completed', 'admin', 'administrator confirms completion'),
  ('in_progress', 'cancelled', 'customer', 'work abandoned before completion under allowed rules'),
  ('in_progress', 'cancelled', 'professional', 'work abandoned before completion under allowed rules'),
  ('in_progress', 'cancelled', 'admin', 'work abandoned before completion under allowed rules'),
  ('in_progress', 'disputed', 'customer', 'problem reported during the job'),
  ('in_progress', 'disputed', 'professional', 'problem reported during the job'),
  ('in_progress', 'disputed', 'admin', 'problem reported during the job'),
  ('completed', 'disputed', 'customer', 'problem reported inside the dispute window'),
  ('completed', 'disputed', 'professional', 'problem reported inside the dispute window'),
  ('completed', 'disputed', 'admin', 'problem reported inside the dispute window'),
  ('disputed', 'completed', 'admin', 'admin resolves the dispute in favour of completion'),
  ('disputed', 'cancelled', 'admin', 'admin resolves the dispute by cancelling')
on conflict do nothing;

-- ---------------------------------------------------------------------
-- Job requests
-- ---------------------------------------------------------------------
create table if not exists public.job_requests (
  id uuid primary key default extensions.gen_random_uuid(),
  customer_id uuid not null references public.profiles (id) on delete cascade,
  category_id uuid not null references public.service_categories (id),
  title text not null check (char_length(title) between 5 and 120),
  description text not null check (char_length(description) between 10 and 5000),
  priority public.job_priority not null default 'normal',
  status public.job_status not null default 'open',
  -- The sub-city of Dire Dawa where the job is. The customer chooses it
  -- from the list; they never send coordinates.
  sub_city_code text not null references public.sub_cities (code),
  -- A copy of the name of that sub-city, so the screens can show it
  -- without a second lookup.
  area_name text not null check (char_length(area_name) between 2 and 120),
  -- The point of the sub-city. It is never collected: it is taken from
  -- `public.sub_cities` and only used to measure the distance between two
  -- sub-cities during the matching.
  location extensions.geography(point, 4326) not null,
  -- Highest match score achieved for this request (evaluation metric).
  match_score numeric(6, 5),
  expires_at timestamptz,
  -- Client supplied key so an accidental double submit cannot create two
  -- requests. NULL means "no de-duplication requested".
  idempotency_key text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (customer_id, idempotency_key)
);

create index if not exists job_requests_customer_idx
  on public.job_requests (customer_id, created_at desc);
create index if not exists job_requests_status_idx
  on public.job_requests (status, created_at desc);
create index if not exists job_requests_category_idx
  on public.job_requests (category_id);
create index if not exists job_requests_location_idx
  on public.job_requests using gist (location);
create index if not exists job_requests_expiry_idx
  on public.job_requests (expires_at)
  where status in ('open', 'matching', 'quoted');

comment on column public.job_requests.match_score is
  'Best match score achieved for this request. Kept for pilot evaluation.';
comment on column public.job_requests.idempotency_key is
  'Client supplied de-duplication key, unique per customer.';

drop trigger if exists job_requests_set_updated_at on public.job_requests;
create trigger job_requests_set_updated_at
  before update on public.job_requests
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------
-- Job photos (private storage objects)
-- ---------------------------------------------------------------------
create table if not exists public.job_photos (
  id uuid primary key default extensions.gen_random_uuid(),
  job_id uuid not null references public.job_requests (id) on delete cascade,
  -- Private bucket path: job-photos/<customerId>/<jobId>/<uuid>.<ext>
  storage_path text not null,
  caption text check (char_length(caption) <= 200),
  sort_order integer not null default 0,
  created_at timestamptz not null default now()
);

create index if not exists job_photos_job_idx on public.job_photos (job_id, sort_order);

-- ---------------------------------------------------------------------
-- Status events (audit trail for every state change)
-- ---------------------------------------------------------------------
create table if not exists public.job_status_events (
  id uuid primary key default extensions.gen_random_uuid(),
  job_id uuid not null references public.job_requests (id) on delete cascade,
  booking_id uuid,
  actor_id uuid references public.profiles (id) on delete set null,
  actor_role text not null default 'system',
  from_status text not null,
  to_status text not null,
  note text,
  created_at timestamptz not null default now()
);

create index if not exists job_status_events_job_idx
  on public.job_status_events (job_id, created_at);
create index if not exists job_status_events_booking_idx
  on public.job_status_events (booking_id);

-- ---------------------------------------------------------------------
-- Create a service request
-- ---------------------------------------------------------------------
create or replace function public.create_job_request(
  p_category_id uuid,
  p_title text,
  p_description text,
  p_sub_city_code text,
  p_priority public.job_priority default 'normal',
  p_idempotency_key text default null
)
returns public.job_requests
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor uuid := public.current_profile_id();
  v_existing public.job_requests;
  v_job public.job_requests;
begin
  if v_actor is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;

  -- Idempotent retry: return the request that was already created.
  if p_idempotency_key is not null and length(btrim(p_idempotency_key)) >= 8 then
    select * into v_existing
    from public.job_requests
    where customer_id = v_actor and idempotency_key = p_idempotency_key;

    if found then
      return v_existing;
    end if;
  end if;

  if not exists (
    select 1 from public.service_categories
    where id = p_category_id and is_active
  ) then
    raise exception 'inactive_or_unknown_category' using errcode = '22023';
  end if;

  -- The location of a request is the sub-city it is in. The name and the
  -- point come from the reference table, never from the client. An unknown
  -- code inserts no row at all.
  insert into public.job_requests (
    customer_id, category_id, title, description, priority, status,
    sub_city_code, area_name, location, idempotency_key, expires_at
  )
  select
    v_actor,
    p_category_id,
    btrim(p_title),
    btrim(p_description),
    coalesce(p_priority, 'normal'),
    'open',
    sc.code,
    sc.name,
    sc.location,
    nullif(btrim(coalesce(p_idempotency_key, '')), ''),
    now() + interval '72 hours'
  from public.sub_cities sc
  where sc.code = p_sub_city_code
  returning * into v_job;

  if v_job.id is null then
    raise exception 'unknown_sub_city' using errcode = '22023';
  end if;

  insert into public.job_status_events (
    job_id, actor_id, actor_role, from_status, to_status, note
  )
  values (v_job.id, v_actor, 'customer', 'open', 'open', 'Request created');

  return v_job;
end;
$$;

comment on function public.create_job_request(uuid, text, text, text, public.job_priority, text) is
  'Create a service request for the signed-in customer. Idempotent when p_idempotency_key is supplied.';

-- ---------------------------------------------------------------------
-- Edit a request (only before it is booked)
-- ---------------------------------------------------------------------
create or replace function public.update_job_request(
  p_job_id uuid,
  p_title text default null,
  p_description text default null,
  p_sub_city_code text default null,
  p_priority public.job_priority default null
)
returns public.job_requests
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor uuid := public.current_profile_id();
  v_job public.job_requests;
begin
  if v_actor is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;

  select * into v_job
  from public.job_requests
  where id = p_job_id
  for update;

  if not found then
    raise exception 'job_not_found' using errcode = 'P0002';
  end if;

  if v_job.customer_id <> v_actor and not public.is_admin() then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if v_job.status not in ('open', 'matching', 'quoted') then
    raise exception 'job_not_editable' using errcode = '22023';
  end if;

  -- The sub-city is only changed when the client sends a known one.
  if p_sub_city_code is not null
     and not exists (
       select 1 from public.sub_cities where code = p_sub_city_code
     ) then
    raise exception 'unknown_sub_city' using errcode = '22023';
  end if;

  update public.job_requests
     set title = coalesce(nullif(btrim(coalesce(p_title, '')), ''), title),
         description = coalesce(nullif(btrim(coalesce(p_description, '')), ''), description),
         sub_city_code = coalesce(p_sub_city_code, sub_city_code),
         area_name = coalesce(
           (select sc.name from public.sub_cities sc where sc.code = p_sub_city_code),
           area_name
         ),
         location = coalesce(
           (select sc.location from public.sub_cities sc where sc.code = p_sub_city_code),
           location
         ),
         priority = coalesce(p_priority, priority)
   where id = p_job_id
   returning * into v_job;

  return v_job;
end;
$$;

-- ---------------------------------------------------------------------
-- Controlled status transition
-- ---------------------------------------------------------------------
create or replace function public.transition_job(
  p_job_id uuid,
  p_to public.job_status,
  p_note text default null
)
returns public.job_requests
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor uuid := public.current_profile_id();
  v_job public.job_requests;
  v_actor_role text;
  v_from_status public.job_status;
begin
  select * into v_job
  from public.job_requests
  where id = p_job_id
  for update;

  if not found then
    raise exception 'job_not_found' using errcode = 'P0002';
  end if;

  -- `booked` is only reachable through public.accept_quotation(), which
  -- performs the atomic "one quotation wins" logic.
  if p_to = 'booked' then
    raise exception 'use_accept_quotation' using errcode = '22023';
  end if;

  -- Resolve which actor role the caller is acting as.
  if public.is_admin() then
    v_actor_role := 'admin';
  elsif v_actor is not null and v_job.customer_id = v_actor then
    v_actor_role := 'customer';
  elsif v_actor is not null and exists (
    select 1 from public.bookings b
    where b.job_id = p_job_id and b.professional_id = v_actor
  ) then
    v_actor_role := 'professional';
  elsif v_actor is null and current_setting('role', true) = 'service_role' then
    v_actor_role := 'system';
  else
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if not exists (
    select 1 from public.job_transition_rules
    where from_status = v_job.status and to_status = p_to and actor = v_actor_role
  ) then
    raise exception 'transition_not_allowed' using errcode = '22023';
  end if;

  v_from_status := v_job.status;

  update public.job_requests
     set status = p_to
   where id = p_job_id
   returning * into v_job;

  insert into public.job_status_events (
    job_id, actor_id, actor_role, from_status, to_status, note
  )
  values (
    p_job_id, v_actor, v_actor_role, v_from_status, p_to, nullif(p_note, '')
  );

  return v_job;
end;
$$;

comment on function public.transition_job(uuid, public.job_status, text) is
  'Apply a status change, enforcing the transition matrix in job_transition_rules.';

-- ---------------------------------------------------------------------
-- Row Level Security
-- ---------------------------------------------------------------------
-- The SELECT policies of job_requests, job_photos and job_status_events
-- live in 20261020001200_storage_and_participant_policies.sql: they join
-- job_matches and bookings, and PostgreSQL resolves every relation named
-- in a policy expression when the policy is created.
--
-- Writes go through the server functions, not direct table writes.
alter table public.job_requests enable row level security;
revoke insert, update, delete on public.job_requests from anon, authenticated;
grant select on public.job_requests to authenticated;

alter table public.job_photos enable row level security;
revoke update on public.job_photos from anon, authenticated;
grant select, insert, delete on public.job_photos to authenticated;

alter table public.job_status_events enable row level security;
revoke insert, update, delete on public.job_status_events from anon, authenticated;
grant select on public.job_status_events to authenticated;


-- ======================================================================
-- FILE: 20261020000700_quotations_and_bookings.sql
======================================================================
-- =====================================================================
-- FixLink Ethiopia - 008: quotations and bookings
-- =====================================================================
-- APPLY ORDER: this file comes AFTER job_requests (the FK target) and
-- BEFORE matching. The matching migration defines
-- public.find_matching_professionals(), a LANGUAGE sql function whose
-- body references public.bookings; a LANGUAGE sql body is analysed when
-- the function is created, so `bookings` has to exist first.
--
-- A quotation is a professional's price for a specific request.
-- A booking is created ONLY by accepting a quotation, and that acceptance
-- is a single atomic database operation:
--
--   * at most one quotation can be accepted per job
--   * the customer who owns the job is the only actor allowed to accept
--   * the quotation must still be valid
--   * a concurrent second acceptance is rejected (the job row is locked)
--
-- All money is Ethiopian Birr (ETB), stored as numeric(12,2).
-- =====================================================================

create table if not exists public.quotations (
  id uuid primary key default extensions.gen_random_uuid(),
  job_id uuid not null references public.job_requests (id) on delete cascade,
  professional_id uuid not null references public.professionals (id) on delete cascade,
  labor_cost_etb numeric(12, 2) not null check (labor_cost_etb >= 0),
  materials_cost_etb numeric(12, 2) not null default 0 check (materials_cost_etb >= 0),
  notes text not null check (char_length(notes) between 10 and 2000),
  proposed_start_at timestamptz,
  valid_until timestamptz not null,
  status public.quotation_status not null default 'submitted',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- A professional may hold at most one live quotation per request.
create unique index if not exists quotations_one_live_per_professional
  on public.quotations (job_id, professional_id)
  where status = 'submitted';

create index if not exists quotations_job_idx
  on public.quotations (job_id, created_at);
create index if not exists quotations_professional_idx
  on public.quotations (professional_id, created_at desc);

comment on column public.quotations.valid_until is
  'The offer stops being selectable after this instant.';

drop trigger if exists quotations_set_updated_at on public.quotations;
create trigger quotations_set_updated_at
  before update on public.quotations
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------
-- Bookings
-- ---------------------------------------------------------------------
create table if not exists public.bookings (
  id uuid primary key default extensions.gen_random_uuid(),
  job_id uuid not null references public.job_requests (id) on delete cascade,
  quotation_id uuid not null references public.quotations (id),
  customer_id uuid not null references public.profiles (id) on delete cascade,
  professional_id uuid not null references public.professionals (id) on delete cascade,
  scheduled_at timestamptz not null,
  status public.booking_status not null default 'booked',
  accepted_at timestamptz not null default now(),
  started_at timestamptz,
  completed_at timestamptz,
  cancelled_at timestamptz,
  cancellation_reason text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- At most one live booking per job. Cancelled bookings are released so a
-- job can be re-booked after a cancellation.
create unique index if not exists bookings_one_active_per_job
  on public.bookings (job_id)
  where status <> 'cancelled';

create index if not exists bookings_customer_idx
  on public.bookings (customer_id, scheduled_at desc);
create index if not exists bookings_professional_idx
  on public.bookings (professional_id, scheduled_at desc);
create index if not exists bookings_job_idx on public.bookings (job_id);

drop trigger if exists bookings_set_updated_at on public.bookings;
create trigger bookings_set_updated_at
  before update on public.bookings
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------
-- Booking transition matrix (mirrors BOOKING_TRANSITIONS in shared-types)
-- ---------------------------------------------------------------------
create table if not exists public.booking_transition_rules (
  from_status public.booking_status not null,
  to_status public.booking_status not null,
  actor text not null check (actor in ('customer', 'professional', 'system', 'admin')),
  condition text not null,
  primary key (from_status, to_status, actor)
);

insert into public.booking_transition_rules (from_status, to_status, actor, condition)
values
  ('booked', 'in_progress', 'professional', 'scheduled work begins'),
  ('booked', 'in_progress', 'customer', 'scheduled work begins'),
  ('booked', 'in_progress', 'admin', 'administrator starts the job'),
  ('booked', 'cancelled', 'customer', 'cancellation rules allow it'),
  ('booked', 'cancelled', 'professional', 'cancellation rules allow it'),
  ('booked', 'cancelled', 'admin', 'cancellation rules allow it'),
  ('booked', 'disputed', 'customer', 'problem reported against the booking'),
  ('booked', 'disputed', 'professional', 'problem reported against the booking'),
  ('booked', 'disputed', 'admin', 'problem reported against the booking'),
  ('in_progress', 'completed', 'customer', 'customer confirms completion'),
  ('in_progress', 'completed', 'system', 'customer confirms completion'),
  ('in_progress', 'completed', 'admin', 'administrator confirms completion'),
  ('in_progress', 'cancelled', 'customer', 'work abandoned before completion under allowed rules'),
  ('in_progress', 'cancelled', 'professional', 'work abandoned before completion under allowed rules'),
  ('in_progress', 'cancelled', 'admin', 'work abandoned before completion under allowed rules'),
  ('in_progress', 'disputed', 'customer', 'problem reported during the job'),
  ('in_progress', 'disputed', 'professional', 'problem reported during the job'),
  ('in_progress', 'disputed', 'admin', 'problem reported during the job'),
  ('completed', 'disputed', 'customer', 'problem reported inside the dispute window'),
  ('completed', 'disputed', 'professional', 'problem reported inside the dispute window'),
  ('completed', 'disputed', 'admin', 'problem reported inside the dispute window'),
  ('disputed', 'completed', 'admin', 'admin resolves the dispute in favour of completion'),
  ('disputed', 'cancelled', 'admin', 'admin resolves the dispute by cancelling')
on conflict do nothing;

-- ---------------------------------------------------------------------
-- Submit a quotation
-- ---------------------------------------------------------------------
create or replace function public.submit_quotation(
  p_job_id uuid,
  p_labor_cost_etb numeric,
  p_materials_cost_etb numeric,
  p_notes text,
  p_proposed_start_at timestamptz default null,
  p_valid_for_hours int default 168
)
returns public.quotations
language plpgsql
security definer
set search_path = public
as $$
declare
  v_professional_id uuid := public.current_professional_id();
  v_job public.job_requests;
  v_quotation public.quotations;
begin
  if v_professional_id is null then
    raise exception 'not_a_professional' using errcode = '42501';
  end if;

  if p_labor_cost_etb is null or p_labor_cost_etb < 0
     or p_materials_cost_etb is null or p_materials_cost_etb < 0 then
    raise exception 'negative_or_missing_cost' using errcode = '22023';
  end if;

  if p_labor_cost_etb > 999999999999.99 or p_materials_cost_etb > 999999999999.99 then
    raise exception 'cost_out_of_range' using errcode = '22023';
  end if;

  if char_length(btrim(coalesce(p_notes, ''))) < 10
     or char_length(btrim(coalesce(p_notes, ''))) > 2000 then
    raise exception 'invalid_notes' using errcode = '22023';
  end if;

  if coalesce(p_valid_for_hours, 168) < 1 or coalesce(p_valid_for_hours, 168) > 2160 then
    raise exception 'invalid_validity' using errcode = '22023';
  end if;

  select * into v_job
  from public.job_requests
  where id = p_job_id
  for update;

  if not found then
    raise exception 'job_not_found' using errcode = 'P0002';
  end if;

  if v_job.status not in ('matching', 'quoted', 'open') then
    raise exception 'job_not_quotable' using errcode = '22023';
  end if;

  -- The professional must be approved, accept requests, and offer the
  -- requested category.
  if not exists (
    select 1
    from public.professionals pr
    join public.professional_services ps on ps.professional_id = pr.id
    where pr.id = v_professional_id
      and pr.verification_status = 'approved'
      and pr.accepts_requests
      and ps.category_id = v_job.category_id
  ) then
    raise exception 'not_eligible_to_quote' using errcode = '42501';
  end if;

  -- The professional must have been matched to this request.
  if not exists (
    select 1 from public.job_matches m
    where m.job_id = p_job_id and m.professional_id = v_professional_id
  ) then
    raise exception 'not_matched_to_job' using errcode = '42501';
  end if;

  -- One live quotation per professional per job: replace the old one.
  update public.quotations
     set status = 'expired', updated_at = now()
   where job_id = p_job_id
     and professional_id = v_professional_id
     and status = 'submitted';

  insert into public.quotations (
    job_id, professional_id, labor_cost_etb, materials_cost_etb,
    notes, proposed_start_at, valid_until, status
  )
  values (
    p_job_id, v_professional_id, p_labor_cost_etb, coalesce(p_materials_cost_etb, 0),
    btrim(p_notes), p_proposed_start_at,
    now() + make_interval(hours => coalesce(p_valid_for_hours, 168)),
    'submitted'
  )
  returning * into v_quotation;

  update public.job_matches
     set response_status = 'quoted'
   where job_id = p_job_id and professional_id = v_professional_id;

  if v_job.status in ('open', 'matching') then
    update public.job_requests set status = 'quoted' where id = p_job_id;

    insert into public.job_status_events (
      job_id, actor_id, actor_role, from_status, to_status, note
    )
    values (
      p_job_id, v_professional_id, 'professional', v_job.status, 'quoted',
      'First quotation received'
    );
  end if;

  perform public.notify(
    v_job.customer_id,
    'quotation.received',
    'You received a quotation',
    format('A professional sent a quotation for "%s".', v_job.title),
    jsonb_build_object('jobId', p_job_id, 'quotationId', v_quotation.id),
    format('quotation:%s', v_quotation.id)
  );

  return v_quotation;
end;
$$;

comment on function public.submit_quotation(uuid, numeric, numeric, text, timestamptz, int) is
  'Submit (or replace) the signed-in professional''s quotation for a matched request.';

-- ---------------------------------------------------------------------
-- Accept a quotation -> create the booking (ATOMIC)
-- ---------------------------------------------------------------------
create or replace function public.accept_quotation(
  p_quotation_id uuid,
  p_scheduled_at timestamptz default null
)
returns public.bookings
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor uuid := public.current_profile_id();
  v_quotation public.quotations;
  v_job public.job_requests;
  v_booking public.bookings;
  v_scheduled timestamptz;
  v_from_status public.job_status;
begin
  if v_actor is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;

  -- Lock the quotation first, then the job. The job lock is what makes
  -- two concurrent acceptances safe: the second transaction waits and
  -- then sees status = 'booked' and is rejected.
  select * into v_quotation
  from public.quotations
  where id = p_quotation_id
  for update;

  if not found then
    raise exception 'quotation_not_found' using errcode = 'P0002';
  end if;

  select * into v_job
  from public.job_requests
  where id = v_quotation.job_id
  for update;

  if not found then
    raise exception 'job_not_found' using errcode = 'P0002';
  end if;

  -- 1. Only the customer who owns the job may accept.
  if v_job.customer_id <> v_actor then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  -- 2. The quotation must belong to this job (implied by the lookup, but
  --    kept explicit for readability of the security contract).
  if v_quotation.job_id <> v_job.id then
    raise exception 'quotation_job_mismatch' using errcode = '22023';
  end if;

  -- 3. The quotation must still be selectable.
  if v_quotation.status <> 'submitted' then
    raise exception 'quotation_not_selectable' using errcode = '22023';
  end if;

  if v_quotation.valid_until <= now() then
    raise exception 'quotation_expired' using errcode = '22023';
  end if;

  -- 4. The job must still be in a bookable state.
  if v_job.status not in ('open', 'matching', 'quoted') then
    raise exception 'job_not_bookable' using errcode = '22023';
  end if;

  -- 5. No other live booking for this job.
  if exists (
    select 1 from public.bookings b
    where b.job_id = v_job.id and b.status <> 'cancelled'
  ) then
    raise exception 'booking_already_exists' using errcode = '23505';
  end if;

  v_scheduled := coalesce(
    p_scheduled_at,
    v_quotation.proposed_start_at,
    now() + interval '24 hours'
  );

  -- 6. The winner is selected, the others are declined.
  update public.quotations
     set status = 'declined', updated_at = now()
   where job_id = v_job.id and id <> v_quotation.id and status = 'submitted';

  update public.quotations
     set status = 'selected', updated_at = now()
   where id = v_quotation.id;

  -- 7. The booking is created.
  insert into public.bookings (
    job_id, quotation_id, customer_id, professional_id, scheduled_at, status, accepted_at
  )
  values (
    v_job.id, v_quotation.id, v_job.customer_id, v_quotation.professional_id,
    v_scheduled, 'booked', now()
  )
  returning * into v_booking;

  -- 8. The job moves to 'booked'.
  v_from_status := v_job.status;
  update public.job_requests
     set status = 'booked'
   where id = v_job.id;

  insert into public.job_status_events (
    job_id, booking_id, actor_id, actor_role, from_status, to_status, note
  )
  values (
    v_job.id, v_booking.id, v_actor, 'customer', v_from_status, 'booked',
    'Quotation accepted'
  );

  -- 9. Both sides are notified.
  perform public.notify(
    v_quotation.professional_id,
    'quotation.selected',
    'Your quotation was accepted',
    format('A customer accepted your quotation for "%s".', v_job.title),
    jsonb_build_object('jobId', v_job.id, 'bookingId', v_booking.id),
    format('quotation-selected:%s', v_quotation.id)
  );

  perform public.notify(
    v_job.customer_id,
    'booking.created',
    'Booking created',
    'Your booking is confirmed. You can message your professional in the app.',
    jsonb_build_object('jobId', v_job.id, 'bookingId', v_booking.id),
    format('booking-created:%s', v_booking.id)
  );

  return v_booking;
end;
$$;

comment on function public.accept_quotation(uuid, timestamptz) is
  'Atomically accept a quotation and create the booking. At most one quotation can win per job.';

-- ---------------------------------------------------------------------
-- Booking lifecycle transitions
-- ---------------------------------------------------------------------
create or replace function public.transition_booking(
  p_booking_id uuid,
  p_to public.booking_status,
  p_reason text default null
)
returns public.bookings
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor uuid := public.current_profile_id();
  v_booking public.bookings;
  v_actor_role text;
  v_from_status public.booking_status;
begin
  select * into v_booking
  from public.bookings
  where id = p_booking_id
  for update;

  if not found then
    raise exception 'booking_not_found' using errcode = 'P0002';
  end if;

  if public.is_admin() then
    v_actor_role := 'admin';
  elsif v_actor is not null and v_booking.customer_id = v_actor then
    v_actor_role := 'customer';
  elsif v_actor is not null and v_booking.professional_id = v_actor then
    v_actor_role := 'professional';
  elsif v_actor is null and current_setting('role', true) = 'service_role' then
    v_actor_role := 'system';
  else
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if not exists (
    select 1 from public.booking_transition_rules
    where from_status = v_booking.status and to_status = p_to and actor = v_actor_role
  ) then
    raise exception 'transition_not_allowed' using errcode = '22023';
  end if;

  if p_to = 'cancelled' and char_length(btrim(coalesce(p_reason, ''))) < 3 then
    raise exception 'cancellation_reason_required' using errcode = '22023';
  end if;

  v_from_status := v_booking.status;

  update public.bookings
     set status = p_to,
         started_at = case when p_to = 'in_progress' then coalesce(started_at, now()) else started_at end,
         completed_at = case when p_to = 'completed' then coalesce(completed_at, now()) else completed_at end,
         cancelled_at = case when p_to = 'cancelled' then coalesce(cancelled_at, now()) else cancelled_at end,
         cancellation_reason = case when p_to = 'cancelled' then p_reason else cancellation_reason end
   where id = p_booking_id
   returning * into v_booking;

  -- Keep the job status in step with the booking status.
  if p_to in ('in_progress', 'completed', 'cancelled', 'disputed') then
    update public.job_requests
       set status = case
         when p_to = 'in_progress' then 'in_progress'::public.job_status
         when p_to = 'completed' then 'completed'::public.job_status
         when p_to = 'cancelled' then 'cancelled'::public.job_status
         else 'disputed'::public.job_status
       end
     where id = v_booking.job_id
       and status not in ('completed', 'cancelled', 'disputed');

    insert into public.job_status_events (
      job_id, booking_id, actor_id, actor_role, from_status, to_status, note
    )
    values (
      v_booking.job_id, v_booking.id, v_actor, v_actor_role, v_from_status, p_to,
      nullif(p_reason, '')
    );
  end if;

  perform public.notify(
    v_booking.customer_id,
    case when p_to = 'completed' then 'booking.completed' else 'booking.updated' end,
    'Booking update',
    format('Your booking is now %s.', p_to),
    jsonb_build_object('jobId', v_booking.job_id, 'bookingId', v_booking.id, 'status', p_to),
    format('booking-status:%s:%s', v_booking.id, p_to)
  );

  perform public.notify(
    v_booking.professional_id,
    case when p_to = 'completed' then 'booking.completed' else 'booking.updated' end,
    'Booking update',
    format('Your booking is now %s.', p_to),
    jsonb_build_object('jobId', v_booking.job_id, 'bookingId', v_booking.id, 'status', p_to),
    format('booking-status:%s:%s', v_booking.id, p_to)
  );

  return v_booking;
end;
$$;

comment on function public.transition_booking(uuid, public.booking_status, text) is
  'Move a booking through its lifecycle, enforcing the booking transition matrix.';

-- ---------------------------------------------------------------------
-- Reschedule a booking (both parties may ask, the other is notified)
-- ---------------------------------------------------------------------
create or replace function public.reschedule_booking(
  p_booking_id uuid,
  p_scheduled_at timestamptz,
  p_reason text default null
)
returns public.bookings
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor uuid := public.current_profile_id();
  v_booking public.bookings;
begin
  select * into v_booking from public.bookings where id = p_booking_id for update;
  if not found then
    raise exception 'booking_not_found' using errcode = 'P0002';
  end if;

  if v_actor is null
     or (v_booking.customer_id <> v_actor
         and v_booking.professional_id <> v_actor
         and not public.is_admin())
  then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if v_booking.status not in ('booked', 'in_progress') then
    raise exception 'booking_not_reschedulable' using errcode = '22023';
  end if;

  update public.bookings
     set scheduled_at = p_scheduled_at
   where id = p_booking_id
   returning * into v_booking;

  insert into public.job_status_events (
    job_id, booking_id, actor_id, actor_role, from_status, to_status, note
  )
  values (
    v_booking.job_id, v_booking.id, v_actor,
    case when v_booking.customer_id = v_actor then 'customer' else 'professional' end,
    v_booking.status, v_booking.status,
    coalesce(nullif(btrim(coalesce(p_reason, '')), ''), 'Rescheduled')
  );

  perform public.notify(
    case when v_booking.customer_id = v_actor
         then v_booking.professional_id
         else v_booking.customer_id end,
    'booking.updated',
    'Schedule changed',
    'The scheduled time for your booking has changed.',
    jsonb_build_object('jobId', v_booking.job_id, 'bookingId', v_booking.id),
    format('booking-reschedule:%s:%s', v_booking.id, extract(epoch from p_scheduled_at)::bigint)
  );

  return v_booking;
end;
$$;

-- ---------------------------------------------------------------------
-- Helper: is the caller a participant of this booking?
-- ---------------------------------------------------------------------
create or replace function public.is_booking_participant(p_booking_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.bookings b
    where b.id = p_booking_id
      and (
        b.customer_id = public.current_profile_id()
        or b.professional_id = public.current_professional_id()
        or public.is_admin()
      )
  );
$$;

-- ---------------------------------------------------------------------
-- Row Level Security
-- ---------------------------------------------------------------------
alter table public.quotations enable row level security;

drop policy if exists "quotations_select_participants" on public.quotations;
create policy "quotations_select_participants"
  on public.quotations
  for select
  to authenticated
  using (
    professional_id = public.current_professional_id()
    or public.is_admin()
    or exists (
      select 1 from public.job_requests j
      where j.id = quotations.job_id
        and j.customer_id = public.current_profile_id()
    )
  );

revoke insert, update, delete on public.quotations from anon, authenticated;
grant select on public.quotations to authenticated;

alter table public.bookings enable row level security;

drop policy if exists "bookings_select_participants" on public.bookings;
create policy "bookings_select_participants"
  on public.bookings
  for select
  to authenticated
  using (
    customer_id = public.current_profile_id()
    or professional_id = public.current_professional_id()
    or public.is_admin()
  );

revoke insert, update, delete on public.bookings from anon, authenticated;
grant select on public.bookings to authenticated;


-- ======================================================================
-- FILE: 20261020000800_matching.sql
======================================================================
-- =====================================================================
-- FixLink Ethiopia - 009: location-aware matching
-- =====================================================================
-- APPLY ORDER: this file comes AFTER quotations_and_bookings.sql, because
-- public.find_matching_professionals() is a LANGUAGE sql function and
-- PostgreSQL analyses its body (including the reference to
-- public.bookings) at CREATE time.
--
-- Ranking formula (SRS Section 10):
--
--   S = 0.35*D + 0.25*R + 0.20*Q + 0.10*A + 0.10*H
--
--   D  normalized geographic proximity
--   R  normalized review / verified-job rating
--   Q  normalized quotation responsiveness
--   A  normalized availability / workload
--   H  normalized relevant experience
--
-- Every component is normalized to [0,1] BEFORE weighting. The TypeScript
-- mirror of these formulas lives in packages/shared-types/src/matching.ts
-- and is covered by unit tests; the two implementations must agree.
--
-- Normalization (identical in SQL and TypeScript):
--
--   D = clamp01(1 - distanceKm / searchRadiusKm)
--       searchRadiusKm = min(professional.serviceRadiusKm, configured cap)
--       Professionals with service_radius_km < 1 are excluded by a CHECK
--       constraint, so the divisor is never zero.
--
--   R = averageRating / 5                      when totalReviews > 0
--     = 0.35                                   otherwise (neutral prior)
--
--   Q = responded / notified                   when notified > 0
--     = 0.5                                    otherwise (neutral prior)
--
--   A = clamp01(1 - activeBookings / maxConcurrentJobs)
--       `accepts_requests = false` is an ELIGIBILITY filter, not a score.
--
--   H = max(clamp01(yearsOfExperience / 15), clamp01(completedJobs / 50))
-- =====================================================================

-- ---------------------------------------------------------------------
-- Tunable configuration (single row, editable by an administrator)
-- ---------------------------------------------------------------------
create table if not exists public.matching_config (
  id integer primary key default 1 check (id = 1),
  batch_size integer not null default 5 check (batch_size between 1 and 50),
  timeout_minutes integer not null default 30 check (timeout_minutes between 1 and 1440),
  radius_expansion_km numeric(5, 2) not null default 5 check (radius_expansion_km > 0),
  max_search_radius_km numeric(5, 2) not null default 25 check (max_search_radius_km > 0),
  max_expansion_rounds integer not null default 3 check (max_expansion_rounds between 0 and 10),
  expiration_hours integer not null default 72 check (expiration_hours between 1 and 720),
  max_concurrent_jobs integer not null default 5 check (max_concurrent_jobs between 1 and 100),
  updated_at timestamptz not null default now()
);

insert into public.matching_config (id) values (1) on conflict (id) do nothing;

comment on table public.matching_config is
  'Runtime-tunable matching parameters. Mirrors DEFAULT_MATCHING_CONFIG in shared-types.';

alter table public.matching_config enable row level security;
drop policy if exists "matching_config_select_authenticated" on public.matching_config;
create policy "matching_config_select_authenticated"
  on public.matching_config
  for select
  to authenticated
  using (true);

drop policy if exists "matching_config_admin_write" on public.matching_config;
create policy "matching_config_admin_write"
  on public.matching_config
  for all
  to authenticated
  using (public.is_admin())
  with check (public.is_admin());

grant select on public.matching_config to authenticated;
grant update on public.matching_config to authenticated;

-- ---------------------------------------------------------------------
-- Matches: who was notified about which request, with the score
-- ---------------------------------------------------------------------
create table if not exists public.job_matches (
  id uuid primary key default extensions.gen_random_uuid(),
  job_id uuid not null references public.job_requests (id) on delete cascade,
  professional_id uuid not null references public.professionals (id) on delete cascade,
  batch_number integer not null default 1,
  rank integer not null default 0,
  score numeric(6, 5) not null check (score between 0 and 1),
  score_components jsonb not null default '{}'::jsonb,
  distance_km numeric(9, 3),
  notified_at timestamptz,
  response_status public.match_response_status not null default 'pending',
  created_at timestamptz not null default now(),
  -- A professional is notified at most once per request.
  unique (job_id, professional_id)
);

create index if not exists job_matches_job_idx
  on public.job_matches (job_id, score desc);
create index if not exists job_matches_professional_idx
  on public.job_matches (professional_id, created_at desc);
create index if not exists job_matches_pending_idx
  on public.job_matches (response_status, notified_at)
  where response_status = 'pending';

comment on table public.job_matches is
  'Notification ledger for the matching algorithm. Doubles as the dataset used to evaluate matching during the pilot.';

-- ---------------------------------------------------------------------
-- Background queue for the matching worker
-- ---------------------------------------------------------------------
create table if not exists public.matching_queue (
  id uuid primary key default extensions.gen_random_uuid(),
  job_id uuid not null references public.job_requests (id) on delete cascade,
  batch_number integer not null default 1,
  radius_km numeric(5, 2),
  status text not null default 'pending'
    check (status in ('pending', 'processing', 'done', 'failed')),
  attempts integer not null default 0,
  last_error text,
  available_at timestamptz not null default now(),
  created_at timestamptz not null default now(),
  processed_at timestamptz
);

create index if not exists matching_queue_pending_idx
  on public.matching_queue (available_at)
  where status = 'pending';

-- ---------------------------------------------------------------------
-- Candidate scoring
-- ---------------------------------------------------------------------
-- Returns the eligible professionals for a request, ranked.
create or replace function public.find_matching_professionals(
  p_job_id uuid,
  p_radius_km numeric default null,
  p_limit int default null
)
returns table (
  professional_id uuid,
  distance_km numeric,
  score numeric,
  components jsonb
)
language sql
stable
security definer
set search_path = public
as $$
with cfg as (
  select * from public.matching_config where id = 1
),
j as (
  select
    jr.id,
    jr.category_id,
    jr.area_name,
    jr.sub_city_code,
    jr.location,
    cfg.max_search_radius_km,
    cfg.max_concurrent_jobs
  from public.job_requests jr
  cross join cfg
  where jr.id = p_job_id
),
-- Step 1: professionals who offer the requested category, are approved,
-- accept requests, and have a base location.
raw as (
  select
    pr.id as professional_id,
    pr.service_radius_km,
    pr.average_rating,
    pr.total_reviews,
    pr.years_of_experience,
    pr.completed_jobs,
    (extensions.st_distance(pr.base_location, j.location) / 1000.0)::numeric as distance_km,
    -- The professional is based in the same sub-city as the job.
    (pr.sub_city_code is not null and pr.sub_city_code = j.sub_city_code) as area_match,
    j.max_search_radius_km,
    j.max_concurrent_jobs
  -- `j` (the request) comes first: a JOIN condition may only reference
  -- relations that appear to its left, and professional_services is
  -- filtered on j.category_id.
  from j
  join public.professionals pr on true
  join public.professional_services ps
    on ps.professional_id = pr.id
   and ps.category_id = j.category_id
  where pr.verification_status = 'approved'
    and pr.accepts_requests
    and pr.service_radius_km >= 1
    and j.location is not null
    and pr.base_location is not null
    and extensions.st_dwithin(
      pr.base_location,
      j.location,
      j.max_search_radius_km * 1000
    )
),
-- Step 2: coverage. A professional covers the job when the job is inside
-- their radius, OR their named service area contains the job area and the
-- job is still inside the platform-wide search cap.
covered as (
  select
    r.*,
    least(r.service_radius_km, coalesce(p_radius_km, r.max_search_radius_km))
      as search_radius_km,
    (
      r.distance_km <= r.service_radius_km
      or (r.area_match and r.distance_km <= r.max_search_radius_km)
    ) as is_covered
  from raw r
),
scored as (
  select
    c.professional_id,
    c.distance_km,
    -- D
    case
      when c.search_radius_km <= 0 then 0
      else greatest(0, least(1, 1 - c.distance_km / c.search_radius_km))
    end as d_score,
    -- R
    case
      when c.total_reviews > 0 then greatest(0, least(1, coalesce(c.average_rating, 0) / 5))
      else 0.35
    end as r_score,
    -- Q
    case
      when coalesce(n.notification_count, 0) > 0
        then greatest(0, least(1, n.response_count::numeric / n.notification_count))
      else 0.5
    end as q_score,
    -- A
    case
      when c.max_concurrent_jobs <= 0 then 0
      else greatest(
        0,
        least(1, 1 - coalesce(b.active_bookings, 0)::numeric / c.max_concurrent_jobs)
      )
    end as a_score,
    -- H
    greatest(
      greatest(0, least(1, c.years_of_experience::numeric / 15)),
      greatest(0, least(1, c.completed_jobs::numeric / 50))
    ) as h_score,
    coalesce(b.active_bookings, 0) as active_bookings
  from covered c
  left join lateral (
    select
      count(*)::int as notification_count,
      count(*) filter (where m.response_status in ('viewed', 'quoted'))::int as response_count
    from public.job_matches m
    where m.professional_id = c.professional_id
  ) n on true
  left join lateral (
    select count(*)::int as active_bookings
    from public.bookings bk
    where bk.professional_id = c.professional_id
      and bk.status in ('booked', 'in_progress')
  ) b on true
  where c.is_covered
)
select
  s.professional_id,
  s.distance_km,
  round(
    (0.35 * s.d_score + 0.25 * s.r_score + 0.20 * s.q_score
     + 0.10 * s.a_score + 0.10 * s.h_score)::numeric,
    5
  ) as score,
  jsonb_build_object(
    'D', round(s.d_score::numeric, 5),
    'R', round(s.r_score::numeric, 5),
    'Q', round(s.q_score::numeric, 5),
    'A', round(s.a_score::numeric, 5),
    'H', round(s.h_score::numeric, 5)
  ) as components
from scored s
order by score desc, s.distance_km asc
limit coalesce(p_limit, 100);
$$;

comment on function public.find_matching_professionals(uuid, numeric, int) is
  'Eligible, scored professionals for a job request, ranked best first.';

-- ---------------------------------------------------------------------
-- Notify a batch of the highest ranked candidates
-- ---------------------------------------------------------------------
create or replace function public.match_job(
  p_job_id uuid,
  p_batch_size int default null,
  p_radius_km numeric default null,
  p_batch_number int default null
)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor uuid := public.current_profile_id();
  v_job public.job_requests;
  v_cfg public.matching_config;
  v_limit int;
  v_batch int;
  v_notified integer := 0;
  v_row record;
begin
  if v_actor is not null
     and not public.is_admin()
     and not exists (
       select 1 from public.job_requests jr
       where jr.id = p_job_id and jr.customer_id = v_actor
     )
  then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  select * into v_job from public.job_requests where id = p_job_id for update;
  if not found then
    raise exception 'job_not_found' using errcode = 'P0002';
  end if;

  if v_job.status not in ('open', 'matching', 'quoted') then
    raise exception 'job_not_matchable' using errcode = '22023';
  end if;

  select * into v_cfg from public.matching_config where id = 1;
  v_limit := coalesce(p_batch_size, v_cfg.batch_size);
  v_batch := coalesce(p_batch_number, 1);

  -- Notify professionals that have NOT been notified for this request yet.
  for v_row in
    with existing as (
      select professional_id from public.job_matches where job_id = p_job_id
    ),
    candidates as (
      select * from public.find_matching_professionals(p_job_id, p_radius_km, v_limit * 4)
    ),
    fresh as (
      select c.*
      from candidates c
      where not exists (
        select 1 from existing e where e.professional_id = c.professional_id
      )
      order by c.score desc
      limit v_limit
    ),
    inserted as (
      insert into public.job_matches (
        job_id, professional_id, batch_number, rank, score,
        score_components, distance_km, notified_at, response_status
      )
      select
        p_job_id, f.professional_id, v_batch,
        row_number() over (order by f.score desc),
        f.score, f.components, f.distance_km, now(), 'pending'
      from fresh f
      returning id, professional_id, score
    )
    select * from inserted
  loop
    perform public.notify(
      (select profile_id from public.professionals where id = v_row.professional_id),
      'job.match_available',
      'New job request near you',
      format('A %s job request in %s is available. Review it and send a quotation.',
        (select sc.name from public.service_categories sc where sc.id = v_job.category_id),
        v_job.area_name),
      jsonb_build_object('jobId', v_job.id, 'matchId', v_row.id),
      format('match:%s:%s', v_job.id, v_row.professional_id)
    );

    v_notified := v_notified + 1;
  end loop;

  if v_notified > 0 then
    update public.job_requests
       set status = 'matching',
           match_score = greatest(coalesce(match_score, 0), 0)
     where id = p_job_id
     and status = 'open';

    if v_job.status = 'open' then
      insert into public.job_status_events (
        job_id, actor_id, actor_role, from_status, to_status, note
      )
      values (
        p_job_id, v_actor, 'system', 'open', 'matching',
        format('Notified %s professional(s)', v_notified)
      );
    end if;
  end if;

  return v_notified;
end;
$$;

comment on function public.match_job(uuid, int, numeric, int) is
  'Notify the highest ranked eligible professionals for a request. Returns how many were newly notified.';

-- ---------------------------------------------------------------------
-- Queue a request for the background matching worker
-- ---------------------------------------------------------------------
create or replace function public.request_matching(
  p_job_id uuid,
  p_batch_number int default 1
)
returns public.matching_queue
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor uuid := public.current_profile_id();
  v_row public.matching_queue;
begin
  if v_actor is not null
     and not public.is_admin()
     and not exists (
       select 1 from public.job_requests jr
       where jr.id = p_job_id and jr.customer_id = v_actor
     )
  then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  insert into public.matching_queue (job_id, batch_number)
  values (p_job_id, coalesce(p_batch_number, 1))
  on conflict do nothing
  returning * into v_row;

  return v_row;
end;
$$;

-- ---------------------------------------------------------------------
-- Expand the search after a timeout with no usable response
-- ---------------------------------------------------------------------
create or replace function public.expand_matching(
  p_job_id uuid
)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor uuid := public.current_profile_id();
  v_job public.job_requests;
  v_cfg public.matching_config;
  v_radius numeric;
  v_batch int;
  v_notified integer;
  v_rounds integer;
begin
  if v_actor is not null and not public.is_admin() then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  select * into v_job from public.job_requests where id = p_job_id for update;
  if not found then
    raise exception 'job_not_found' using errcode = 'P0002';
  end if;

  select * into v_cfg from public.matching_config where id = 1;

  select count(distinct batch_number) into v_rounds
  from public.job_matches
  where job_id = p_job_id;

  if v_rounds >= v_cfg.max_expansion_rounds then
    -- No more rounds: the request is left open for manual review and
    -- eventually expired by the maintenance job.
    insert into public.job_status_events (
      job_id, actor_id, actor_role, from_status, to_status, note
    )
    values (
      p_job_id, v_actor, 'system', v_job.status, v_job.status,
      'Maximum matching expansion rounds reached'
    );
    return 0;
  end if;

  v_batch := v_rounds + 1;
  v_radius := least(
    v_cfg.max_search_radius_km,
    v_cfg.radius_expansion_km * v_batch
  );

  v_notified := public.match_job(p_job_id, v_cfg.batch_size, v_radius, v_batch);

  insert into public.job_status_events (
    job_id, actor_id, actor_role, from_status, to_status, note
  )
  values (
    p_job_id, v_actor, 'system', v_job.status, v_job.status,
    format('Matching expanded to round %s (radius %s km), %s new professional(s)',
      v_batch, v_radius, v_notified)
  );

  return v_notified;
end;
$$;

-- ---------------------------------------------------------------------
-- Keep the professional response rate up to date
-- ---------------------------------------------------------------------
create or replace function public.refresh_professional_response_rate()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  update public.professionals p
     set quotation_response_rate = sub.rate
  from (
    select
      count(*)::numeric as total,
      count(*) filter (where m.response_status in ('viewed', 'quoted'))::numeric as responded
    from public.job_matches m
    where m.professional_id = new.professional_id
  ) sub
  where p.id = new.professional_id
    and sub.total > 0
    and sub.responded / sub.total <> coalesce(p.quotation_response_rate, -1);

  return new;
end;
$$;

drop trigger if exists job_matches_refresh_rate on public.job_matches;
create trigger job_matches_refresh_rate
  after insert or update of response_status on public.job_matches
  for each row execute function public.refresh_professional_response_rate();

-- ---------------------------------------------------------------------
-- Row Level Security
-- ---------------------------------------------------------------------
alter table public.job_matches enable row level security;

drop policy if exists "job_matches_select_participants" on public.job_matches;
create policy "job_matches_select_participants"
  on public.job_matches
  for select
  to authenticated
  using (
    professional_id = public.current_professional_id()
    or public.is_admin()
    or exists (
      select 1 from public.job_requests j
      where j.id = job_matches.job_id
        and j.customer_id = public.current_profile_id()
    )
  );

revoke insert, update, delete on public.job_matches from anon, authenticated;
grant select on public.job_matches to authenticated;

alter table public.matching_queue enable row level security;
revoke all on public.matching_queue from anon, authenticated;


-- ======================================================================
-- FILE: 20261020000900_messages.sql
======================================================================
-- =====================================================================
-- FixLink Ethiopia - 010: private booking conversations
-- =====================================================================
-- Messages belong to a BOOKING, never to a job. Only the two people in
-- that booking (customer + booked professional) and administrators may
-- read or send them. There is no channel that exposes conversation
-- content to other users, and the Realtime subscription is filtered by
-- the same RLS policy as a normal read.
-- =====================================================================

create table if not exists public.messages (
  id uuid primary key default extensions.gen_random_uuid(),
  booking_id uuid not null references public.bookings (id) on delete cascade,
  sender_id uuid not null references public.profiles (id) on delete cascade,
  body text not null check (char_length(btrim(body)) between 1 and 5000),
  read_at timestamptz,
  created_at timestamptz not null default now()
);

create index if not exists messages_booking_idx
  on public.messages (booking_id, created_at);
create index if not exists messages_unread_idx
  on public.messages (booking_id)
  where read_at is null;

-- ---------------------------------------------------------------------
-- Send a message
-- ---------------------------------------------------------------------
create or replace function public.send_message(
  p_booking_id uuid,
  p_body text
)
returns public.messages
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor uuid := public.current_profile_id();
  v_message public.messages;
  v_customer uuid;
  v_professional uuid;
begin
  if v_actor is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;

  if char_length(btrim(coalesce(p_body, ''))) < 1
     or char_length(btrim(p_body)) > 5000 then
    raise exception 'invalid_message_body' using errcode = '22023';
  end if;

  select b.customer_id, b.professional_id
    into v_customer, v_professional
  from public.bookings b
  where b.id = p_booking_id;

  if not found then
    raise exception 'booking_not_found' using errcode = 'P0002';
  end if;

  if v_actor <> v_customer and v_actor <> v_professional then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  insert into public.messages (booking_id, sender_id, body)
  values (p_booking_id, v_actor, btrim(p_body))
  returning * into v_message;

  -- Notify the other participant.
  perform public.notify(
    case when v_actor = v_customer then v_professional else v_customer end,
    'message.received',
    'New message',
    left(btrim(p_body), 120),
    jsonb_build_object('bookingId', p_booking_id, 'messageId', v_message.id),
    format('message:%s', v_message.id)
  );

  return v_message;
end;
$$;

comment on function public.send_message(uuid, text) is
  'Send a message inside a booking conversation. Only booking participants may send.';

-- ---------------------------------------------------------------------
-- Mark the other participant''s messages as read
-- ---------------------------------------------------------------------
create or replace function public.mark_messages_read(
  p_booking_id uuid
)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor uuid := public.current_profile_id();
  v_count integer;
begin
  if v_actor is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;

  update public.messages
     set read_at = now()
   where booking_id = p_booking_id
     and read_at is null
     and sender_id <> v_actor
     and (
       v_actor = (select customer_id from public.bookings where id = p_booking_id)
       or v_actor = (select professional_id from public.professionals where id = p_booking_id)
     );

  get diagnostics v_count = row_count;
  return v_count;
end;
$$;

-- ---------------------------------------------------------------------
-- Row Level Security
-- ---------------------------------------------------------------------
alter table public.messages enable row level security;

drop policy if exists "messages_select_participants" on public.messages;
create policy "messages_select_participants"
  on public.messages
  for select
  to authenticated
  using (
    sender_id = public.current_profile_id()
    or exists (
      select 1 from public.bookings b
      where b.id = messages.booking_id
        and (
          b.customer_id = public.current_profile_id()
          or b.professional_id = public.current_professional_id()
        )
    )
    or public.is_admin()
  );

-- Sending goes through public.send_message() only.
revoke insert, update, delete on public.messages from anon, authenticated;
grant select on public.messages to authenticated;


-- ======================================================================
-- FILE: 20261020001000_reviews_reports_admin.sql
======================================================================
-- =====================================================================
-- FixLink Ethiopia - 011: reviews, reports, account restrictions
-- =====================================================================
-- Reviews are tied to a GENUINE completed booking: the reviewer must be
-- the customer of a booking whose status is 'completed'. The rating
-- summary on `professionals` is maintained by a trigger, so it can never
-- drift from the underlying reviews.
--
-- Reports (complaints) can be filed against a user or a booking and are
-- resolved by administrators, with the resolution recorded.
-- =====================================================================

create table if not exists public.reviews (
  id uuid primary key default extensions.gen_random_uuid(),
  booking_id uuid not null unique references public.bookings (id) on delete cascade,
  reviewer_id uuid not null references public.profiles (id) on delete cascade,
  professional_id uuid not null references public.professionals (id) on delete cascade,
  rating integer not null check (rating between 1 and 5),
  comment text check (char_length(comment) <= 1000),
  created_at timestamptz not null default now()
);

create index if not exists reviews_professional_idx
  on public.reviews (professional_id, created_at desc);
create index if not exists reviews_reviewer_idx on public.reviews (reviewer_id);

comment on table public.reviews is
  'Verified-job reviews. One review per booking; the booking must be completed.';

-- ---------------------------------------------------------------------
-- Reports / complaints
-- ---------------------------------------------------------------------
create table if not exists public.reports (
  id uuid primary key default extensions.gen_random_uuid(),
  reporter_id uuid not null references public.profiles (id) on delete cascade,
  reported_user_id uuid references public.profiles (id) on delete set null,
  booking_id uuid references public.bookings (id) on delete set null,
  reason public.report_reason not null,
  details text not null check (char_length(details) between 10 and 2000),
  status public.report_status not null default 'open',
  resolution text,
  resolved_by uuid references public.profiles (id) on delete set null,
  resolved_at timestamptz,
  created_at timestamptz not null default now(),
  -- A report must point at something.
  check (reported_user_id is not null or booking_id is not null)
);

create index if not exists reports_status_idx on public.reports (status, created_at desc);
create index if not exists reports_reporter_idx on public.reports (reporter_id, created_at desc);
create index if not exists reports_booking_idx on public.reports (booking_id);

-- ---------------------------------------------------------------------
-- Submit a review
-- ---------------------------------------------------------------------
create or replace function public.create_review(
  p_booking_id uuid,
  p_rating integer,
  p_comment text default null
)
returns public.reviews
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor uuid := public.current_profile_id();
  v_booking public.bookings;
  v_review public.reviews;
begin
  if v_actor is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;

  if p_rating is null or p_rating < 1 or p_rating > 5 then
    raise exception 'invalid_rating' using errcode = '22023';
  end if;

  if p_comment is not null and char_length(p_comment) > 1000 then
    raise exception 'comment_too_long' using errcode = '22023';
  end if;

  select * into v_booking
  from public.bookings
  where id = p_booking_id
  for update;

  if not found then
    raise exception 'booking_not_found' using errcode = 'P0002';
  end if;

  -- Only the customer of the booking may review it.
  if v_booking.customer_id <> v_actor then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  -- Only a completed booking is reviewable.
  if v_booking.status <> 'completed' then
    raise exception 'booking_not_reviewable' using errcode = '22023';
  end if;

  insert into public.reviews (booking_id, reviewer_id, professional_id, rating, comment)
  values (p_booking_id, v_actor, v_booking.professional_id, p_rating, nullif(btrim(coalesce(p_comment, '')), ''))
  returning * into v_review;

  perform public.notify(
    v_booking.professional_id,
    'review.received',
    'You received a review',
    format('You received a %s star review for a completed job.', p_rating),
    jsonb_build_object('bookingId', p_booking_id, 'reviewId', v_review.id),
    format('review:%s', v_review.id)
  );

  return v_review;
end;
$$;

-- ---------------------------------------------------------------------
-- Keep the professional rating summary in step with the reviews
-- ---------------------------------------------------------------------
create or replace function public.refresh_professional_rating()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_professional uuid := coalesce(new.professional_id, old.professional_id);
begin
  update public.professionals p
     set average_rating = sub.avg_rating,
         total_reviews = sub.total_reviews
  from (
    select
      count(*)::int as total_reviews,
      round(avg(r.rating)::numeric, 2) as avg_rating
    from public.reviews r
    where r.professional_id = v_professional
  ) sub
  where p.id = v_professional;

  return coalesce(new, old);
end;
$$;

drop trigger if exists reviews_refresh_rating on public.reviews;
create trigger reviews_refresh_rating
  after insert or update or delete on public.reviews
  for each row execute function public.refresh_professional_rating();

-- ---------------------------------------------------------------------
-- Count completed jobs for the professional
-- ---------------------------------------------------------------------
create or replace function public.refresh_professional_completed_jobs()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  update public.professionals p
     set completed_jobs = sub.completed
  from (
    select count(*)::int as completed
    from public.bookings b
    where b.professional_id = coalesce(new.professional_id, old.professional_id)
      and b.status = 'completed'
  ) sub
  where p.id = coalesce(new.professional_id, old.professional_id);

  return coalesce(new, old);
end;
$$;

drop trigger if exists bookings_refresh_completed_jobs on public.bookings;
create trigger bookings_refresh_completed_jobs
  after insert or update of status on public.bookings
  for each row execute function public.refresh_professional_completed_jobs();

-- ---------------------------------------------------------------------
-- File a report / complaint
-- ---------------------------------------------------------------------
create or replace function public.create_report(
  p_reported_user_id uuid default null,
  p_booking_id uuid default null,
  p_reason public.report_reason default 'other',
  p_details text default null
)
returns public.reports
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor uuid := public.current_profile_id();
  v_report public.reports;
begin
  if v_actor is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;

  if p_reported_user_id is null and p_booking_id is null then
    raise exception 'report_target_required' using errcode = '22023';
  end if;

  if char_length(btrim(coalesce(p_details, ''))) < 10
     or char_length(btrim(coalesce(p_details, ''))) > 2000 then
    raise exception 'invalid_details' using errcode = '22023';
  end if;

  -- A customer may only report a booking they took part in.
  if p_booking_id is not null and not public.is_booking_participant(p_booking_id) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  insert into public.reports (reporter_id, reported_user_id, booking_id, reason, details)
  values (v_actor, p_reported_user_id, p_booking_id, coalesce(p_reason, 'other'), btrim(p_details))
  returning * into v_report;

  perform public.notify(
    v_actor,
    'report.filed',
    'Report received',
    'Your report has been filed. An administrator will review it.',
    jsonb_build_object('reportId', v_report.id),
    format('report-filed:%s', v_report.id)
  );

  return v_report;
end;
$$;

-- ---------------------------------------------------------------------
-- Administrator: resolve a report
-- ---------------------------------------------------------------------
create or replace function public.resolve_report(
  p_report_id uuid,
  p_status public.report_status,
  p_resolution text
)
returns public.reports
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor uuid := public.current_profile_id();
  v_report public.reports;
begin
  if not public.is_admin() then
    raise exception 'admin_required' using errcode = '42501';
  end if;

  if p_status not in ('resolved', 'dismissed', 'investigating') then
    raise exception 'invalid_status' using errcode = '22023';
  end if;

  if char_length(btrim(coalesce(p_resolution, ''))) < 5 then
    raise exception 'resolution_required' using errcode = '22023';
  end if;

  update public.reports
     set status = p_status,
         resolution = btrim(p_resolution),
         resolved_by = v_actor,
         resolved_at = now()
   where id = p_report_id
   returning * into v_report;

  if v_report.id is null then
    raise exception 'report_not_found' using errcode = 'P0002';
  end if;

  insert into public.audit_log (actor_id, actor_role, action, entity_type, entity_id, details)
  values (
    v_actor, 'admin', 'report.' || p_status::text, 'report', p_report_id,
    jsonb_build_object('resolution', p_resolution)
  );

  perform public.notify(
    v_report.reporter_id,
    'report.resolved',
    'Report update',
    format('Your report was marked as %s.', p_status),
    jsonb_build_object('reportId', p_report_id, 'status', p_status),
    format('report-status:%s:%s', p_report_id, p_status)
  );

  return v_report;
end;
$$;

-- ---------------------------------------------------------------------
-- Administrator: suspend / close / reinstate an account
-- ---------------------------------------------------------------------
create or replace function public.set_account_status(
  p_profile_id uuid,
  p_status public.account_status,
  p_reason text default null
)
returns public.profiles
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor uuid := public.current_profile_id();
  v_profile public.profiles;
  v_previous public.account_status;
begin
  if not public.is_admin() then
    raise exception 'admin_required' using errcode = '42501';
  end if;

  if p_status not in ('active', 'suspended', 'closed') then
    raise exception 'invalid_status' using errcode = '22023';
  end if;

  select * into v_profile
  from public.profiles
  where id = p_profile_id
  for update;

  if not found then
    raise exception 'profile_not_found' using errcode = 'P0002';
  end if;

  v_previous := v_profile.account_status;

  update public.profiles
     set account_status = p_status
   where id = p_profile_id
   returning * into v_profile;

  insert into public.audit_log (actor_id, actor_role, action, entity_type, entity_id, details)
  values (
    v_actor, 'admin', 'account.status_' || p_status::text, 'profile', p_profile_id,
    jsonb_build_object('previousStatus', v_previous, 'newStatus', p_status, 'reason', p_reason)
  );

  perform public.notify(
    p_profile_id,
    'account.restricted',
    'Account status updated',
    case
      when p_status = 'suspended' then 'Your account has been suspended. Contact support for details.'
      when p_status = 'closed' then 'Your account has been closed.'
      else 'Your account is active again.'
    end,
    jsonb_build_object('status', p_status),
    format('account-status:%s:%s', p_profile_id, p_status)
  );

  return v_profile;
end;
$$;

-- ---------------------------------------------------------------------
-- Grant / revoke the administrator role (bootstrap + administration)
-- ---------------------------------------------------------------------
-- The FIRST administrator is granted by a database administrator running
-- this function directly in the Supabase SQL editor. There is no
-- self-service path to `admin`: the function refuses to run for a caller
-- who is not already an administrator, except for the very first one.
create or replace function public.grant_admin(
  p_profile_id uuid,
  p_reason text default 'bootstrap'
)
returns public.profiles
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor uuid := public.current_profile_id();
  v_profile public.profiles;
  v_admin_count integer;
begin
  select count(*) into v_admin_count
  from public.profiles
  where role = 'admin';

  -- Bootstrap: the very first administrator, run from the SQL editor
  -- (where the caller is the `postgres` role and has no Auth session).
  if v_admin_count = 0 and (
    v_actor is null
    or current_setting('role', true) in ('service_role', 'postgres', 'supabase_admin')
  ) then
    update public.profiles
       set role = 'admin'
     where id = p_profile_id
     returning * into v_profile;

    insert into public.audit_log (actor_id, actor_role, action, entity_type, entity_id, details)
    values (v_actor, 'admin', 'profile.grant_admin', 'profile', p_profile_id,
      jsonb_build_object('reason', p_reason));

    return v_profile;
  end if;

  if not public.is_admin() then
    raise exception 'admin_required' using errcode = '42501';
  end if;

  update public.profiles
     set role = 'admin'
   where id = p_profile_id
   returning * into v_profile;

  insert into public.audit_log (actor_id, actor_role, action, entity_type, entity_id, details)
  values (v_actor, 'admin', 'profile.grant_admin', 'profile', p_profile_id,
    jsonb_build_object('reason', p_reason));

  return v_profile;
end;
$$;

comment on function public.grant_admin(uuid, text) is
  'Grant the admin role. The first administrator may be bootstrapped from the SQL editor; afterwards only admins may call it.';

-- ---------------------------------------------------------------------
-- Row Level Security
-- ---------------------------------------------------------------------
alter table public.reviews enable row level security;

drop policy if exists "reviews_select_public" on public.reviews;
create policy "reviews_select_public"
  on public.reviews
  for select
  to anon, authenticated
  using (
    exists (
      select 1 from public.professionals pr
      where pr.id = reviews.professional_id
        and pr.verification_status = 'approved'
    )
    or reviewer_id = public.current_profile_id()
    or public.is_admin()
  );

revoke insert, update, delete on public.reviews from anon, authenticated;
grant select on public.reviews to anon, authenticated;

alter table public.reports enable row level security;

drop policy if exists "reports_select_participants" on public.reports;
create policy "reports_select_participants"
  on public.reports
  for select
  to authenticated
  using (
    reporter_id = public.current_profile_id()
    or reported_user_id = public.current_profile_id()
    or public.is_admin()
  );

revoke insert, update, delete on public.reports from anon, authenticated;
grant select on public.reports to authenticated;


-- ======================================================================
-- FILE: 20261020001100_realtime_grants_idempotency.sql
======================================================================
-- =====================================================================
-- FixLink Ethiopia - 012: realtime, idempotency, final grants
-- =====================================================================
-- 1. `idempotency_keys` lets the trusted web API routes make important
--    create operations safe against accidental retries.
-- 2. The Realtime publication exposes only the tables the apps actually
--    subscribe to. RLS still applies to every subscription, so a
--    subscriber only receives rows it is allowed to read.
-- 3. Final grants: application roles get the minimum they need; every
--    privileged operation goes through a SECURITY DEFINER function.
-- =====================================================================

-- ---------------------------------------------------------------------
-- Idempotency keys for trusted server endpoints
-- ---------------------------------------------------------------------
create table if not exists public.idempotency_keys (
  id uuid primary key default extensions.gen_random_uuid(),
  user_id uuid not null references public.profiles (id) on delete cascade,
  operation text not null,
  key text not null,
  response jsonb,
  created_at timestamptz not null default now(),
  unique (user_id, operation, key)
);

create index if not exists idempotency_keys_created_idx
  on public.idempotency_keys (created_at);

alter table public.idempotency_keys enable row level security;
revoke all on public.idempotency_keys from anon, authenticated;

comment on table public.idempotency_keys is
  'Replay protection for trusted server endpoints. A repeated key returns the stored response.';

-- ---------------------------------------------------------------------
-- Realtime publication
-- ---------------------------------------------------------------------
-- `alter publication ... add table` fails if the table is already a
-- member, so guard each statement.
do $$
declare
  v_table text;
  v_tables text[] := array[
    'messages', 'notifications', 'job_matches', 'quotations',
    'bookings', 'job_requests'
  ];
begin
  if not exists (
    select 1 from pg_publication where pubname = 'supabase_realtime'
  ) then
    return;
  end if;

  foreach v_table in array v_tables
  loop
    if not exists (
      select 1
      from pg_publication_tables
      where pubname = 'supabase_realtime'
        and schemaname = 'public'
        and tablename = v_table
    ) then
      execute format(
        'alter publication supabase_realtime add table public.%I', v_table
      );
    end if;
  end loop;
end
$$;

-- ---------------------------------------------------------------------
-- Final grants
-- ---------------------------------------------------------------------
-- Read access for the application roles. Write access is granted per
-- table above and is deliberately narrow; sensitive writes happen only
-- inside SECURITY DEFINER functions.
grant usage on schema public to anon, authenticated;
grant select on public.profiles to authenticated;
grant select on public.service_categories to anon, authenticated;
grant select on public.professionals to anon, authenticated;
grant select on public.professional_services to anon, authenticated;
grant select on public.service_areas to anon, authenticated;
grant select on public.job_requests to authenticated;
grant select on public.job_photos to authenticated;
grant select on public.job_status_events to authenticated;
grant select on public.job_matches to authenticated;
grant select on public.quotations to authenticated;
grant select on public.bookings to authenticated;
grant select on public.messages to authenticated;
grant select on public.notifications to authenticated;
grant select on public.reviews to anon, authenticated;
grant select on public.reports to authenticated;
grant select on public.verification_documents to authenticated;
grant select on public.matching_config to authenticated;
grant select on public.audit_log to authenticated;

-- Every SECURITY DEFINER function is executable by the application roles.
grant execute on function public.ensure_profile(text, text, text) to authenticated;
grant execute on function public.start_as_professional(int, text) to authenticated;
grant execute on function public.update_professional_profile(
  text, int, boolean, numeric, text, double precision, double precision
) to authenticated;
grant execute on function public.set_professional_services(jsonb) to authenticated;
grant execute on function public.set_service_areas(text[]) to authenticated;
grant execute on function public.create_job_request(
  uuid, text, text, text, double precision, double precision,
  public.location_source, public.job_priority, text
) to authenticated;
grant execute on function public.update_job_request(
  uuid, text, text, text, double precision, double precision, public.job_priority
) to authenticated;
grant execute on function public.transition_job(uuid, public.job_status, text) to authenticated;
grant execute on function public.match_job(uuid, int, numeric, int) to authenticated;
grant execute on function public.request_matching(uuid, int) to authenticated;
grant execute on function public.expand_matching(uuid) to service_role;
grant execute on function public.submit_quotation(
  uuid, numeric, numeric, text, timestamptz, int
) to authenticated;
grant execute on function public.accept_quotation(uuid, timestamptz) to authenticated;
grant execute on function public.transition_booking(uuid, public.booking_status, text) to authenticated;
grant execute on function public.reschedule_booking(uuid, timestamptz, text) to authenticated;
grant execute on function public.send_message(uuid, text) to authenticated;
grant execute on function public.mark_messages_read(uuid) to authenticated;
grant execute on function public.mark_notifications_read(uuid[]) to authenticated;
grant execute on function public.register_device_token(text, public.device_platform) to authenticated;
grant execute on function public.create_review(uuid, integer, text) to authenticated;
grant execute on function public.create_report(uuid, uuid, public.report_reason, text) to authenticated;
grant execute on function public.set_verification_status(uuid, public.verification_status, text) to authenticated;
grant execute on function public.resolve_report(uuid, public.report_status, text) to authenticated;
grant execute on function public.set_account_status(uuid, public.account_status, text) to authenticated;
