-- ======================================================================
-- FILE: 20261020001200_storage_and_participant_policies.sql
======================================================================
-- =====================================================================
-- FixLink Ethiopia - 013: storage buckets and participant policies
-- =====================================================================
-- THIS FILE MUST BE APPLIED LAST.
--
-- Why it exists
-- -------------
-- A few Row Level Security policies join tables that are created later
-- in the migration chain:
--
--   job_requests -> job_matches -> quotations -> bookings
--
-- PostgreSQL resolves EVERY relation named in a policy expression when
-- the policy is created (`CREATE POLICY` parses and analyses the
-- expression). A policy that mentions `public.job_matches` therefore
-- fails with
--
--   ERROR: 42P01: relation "public.job_matches" does not exist
--
-- if that table has not been created yet. The same is true for
-- `LANGUAGE sql` function bodies, which are analysed at CREATE time.
--
-- The tables themselves stay in their own migration files (see
-- 20261020000600_job_requests.sql). Only the policies that span more
-- than one table are collected here, together with the storage buckets
-- and the storage policies, which also reference job_requests and
-- job_matches.
--
-- Everything in this file is idempotent: `drop policy if exists` runs
-- first, so re-running the file is safe.
-- =====================================================================

-- ---------------------------------------------------------------------
-- Storage buckets
-- ---------------------------------------------------------------------
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values
  ('job-photos', 'job-photos', false, 5242880, array['image/jpeg', 'image/png', 'image/webp']),
  ('avatars', 'avatars', true, 2097152, array['image/jpeg', 'image/png', 'image/webp']),
  ('verification-documents', 'verification-documents', false, 10485760, array['image/jpeg', 'image/png', 'application/pdf'])
on conflict (id) do update
  set public = excluded.public,
      file_size_limit = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

-- ---------------------------------------------------------------------
-- Storage policies
-- ---------------------------------------------------------------------
-- Object paths:
--   job-photos              : <profileId>/<jobId>/<uuid>.<ext>
--   verification-documents  : <professionalId>/<docId>.<ext>
--   avatars                 : <profileId>/<uuid>.<ext>

drop policy if exists "job_photos_insert_own_folder" on storage.objects;
create policy "job_photos_insert_own_folder"
  on storage.objects
  for insert
  to authenticated
  with check (
    bucket_id = 'job-photos'
    and (storage.foldername(name))[1] = public.current_profile_id()::text
  );

drop policy if exists "job_photos_read_participants" on storage.objects;
create policy "job_photos_read_participants"
  on storage.objects
  for select
  to authenticated
  using (
    bucket_id = 'job-photos'
    and (
      (storage.foldername(name))[1] = public.current_profile_id()::text
      or public.is_admin()
      or exists (
        select 1
        from public.job_requests j
        join public.job_matches m on m.job_id = j.id
        where j.id::text = (storage.foldername(name))[2]
          and m.professional_id = public.current_professional_id()
      )
    )
  );

drop policy if exists "job_photos_delete_own_folder" on storage.objects;
create policy "job_photos_delete_own_folder"
  on storage.objects
  for delete
  to authenticated
  using (
    bucket_id = 'job-photos'
    and (storage.foldername(name))[1] = public.current_profile_id()::text
  );

drop policy if exists "verification_documents_insert_own" on storage.objects;
create policy "verification_documents_insert_own"
  on storage.objects
  for insert
  to authenticated
  with check (
    bucket_id = 'verification-documents'
    and (storage.foldername(name))[1] = public.current_professional_id()::text
  );

drop policy if exists "verification_documents_read_owner_or_admin" on storage.objects;
create policy "verification_documents_read_owner_or_admin"
  on storage.objects
  for select
  to authenticated
  using (
    bucket_id = 'verification-documents'
    and (
      (storage.foldername(name))[1] = public.current_professional_id()::text
      or public.is_admin()
    )
  );

drop policy if exists "verification_documents_delete_own" on storage.objects;
create policy "verification_documents_delete_own"
  on storage.objects
  for delete
  to authenticated
  using (
    bucket_id = 'verification-documents'
    and (storage.foldername(name))[1] = public.current_professional_id()::text
  );

drop policy if exists "avatars_insert_own_folder" on storage.objects;
create policy "avatars_insert_own_folder"
  on storage.objects
  for insert
  to authenticated
  with check (
    bucket_id = 'avatars'
    and (storage.foldername(name))[1] = public.current_profile_id()::text
  );

drop policy if exists "avatars_read_public" on storage.objects;
create policy "avatars_read_public"
  on storage.objects
  for select
  to anon, authenticated
  using (bucket_id = 'avatars');

-- ---------------------------------------------------------------------
-- Job requests: who may read a request
-- ---------------------------------------------------------------------
-- A customer sees their own requests. A professional sees a request only
-- once they have been matched to it. Administrators see everything.
drop policy if exists "job_requests_select_participants" on public.job_requests;
create policy "job_requests_select_participants"
  on public.job_requests
  for select
  to authenticated
  using (
    customer_id = public.current_profile_id()
    or public.is_admin()
    or exists (
      select 1 from public.job_matches m
      where m.job_id = job_requests.id
        and m.professional_id = public.current_professional_id()
    )
    or exists (
      select 1 from public.bookings b
      where b.job_id = job_requests.id
        and b.professional_id = public.current_professional_id()
    )
  );

-- ---------------------------------------------------------------------
-- Job photos: only the participants of the request may see them
-- ---------------------------------------------------------------------
drop policy if exists "job_photos_select_participants" on public.job_photos;
create policy "job_photos_select_participants"
  on public.job_photos
  for select
  to authenticated
  using (
    exists (
      select 1 from public.job_requests j
      where j.id = job_photos.job_id
        and (
          j.customer_id = public.current_profile_id()
          or public.is_admin()
          or exists (
            select 1 from public.job_matches m
            where m.job_id = j.id
              and m.professional_id = public.current_professional_id()
          )
          or exists (
            select 1 from public.bookings b
            where b.job_id = j.id
              and b.professional_id = public.current_professional_id()
          )
        )
    )
  );

drop policy if exists "job_photos_insert_owner" on public.job_photos;
create policy "job_photos_insert_owner"
  on public.job_photos
  for insert
  to authenticated
  with check (
    exists (
      select 1 from public.job_requests j
      where j.id = job_photos.job_id
        and j.customer_id = public.current_profile_id()
    )
  );

drop policy if exists "job_photos_delete_owner" on public.job_photos;
create policy "job_photos_delete_owner"
  on public.job_photos
  for delete
  to authenticated
  using (
    exists (
      select 1 from public.job_requests j
      where j.id = job_photos.job_id
        and j.customer_id = public.current_profile_id()
    )
  );

-- ---------------------------------------------------------------------
-- Status events: the audit trail is visible to the participants only
-- ---------------------------------------------------------------------
drop policy if exists "job_status_events_select_participants" on public.job_status_events;
create policy "job_status_events_select_participants"
  on public.job_status_events
  for select
  to authenticated
  using (
    exists (
      select 1 from public.job_requests j
      where j.id = job_status_events.job_id
        and (
          j.customer_id = public.current_profile_id()
          or public.is_admin()
          or exists (
            select 1 from public.bookings b
            where b.job_id = j.id
              and b.professional_id = public.current_professional_id()
          )
        )
    )
  );


-- ======================================================================
-- FILE: 20261020001300_lock_down_privileges.sql
======================================================================
-- =====================================================================
-- FixLink Ethiopia - 014: lock down table privileges
-- =====================================================================
-- Supabase grants ALL privileges on every table in the `public` schema
-- to `anon` and `authenticated` by default (via default privileges).
-- The migrations revoke INSERT/UPDATE/DELETE where writes must go through
-- a SECURITY DEFINER function, but that leaves three problems:
--
--   1. The two transition matrices had NO Row Level Security policy and
--      NO revoke, so an anonymous client could read AND rewrite the
--      authoritative state machine of the whole platform.
--
--   2. TRUNCATE, REFERENCES and TRIGGER bypass Row Level Security
--      completely: a policy can never stop `TRUNCATE profiles`.
--
--   3. `anon` kept SELECT on private tables. RLS hides the rows, but the
--      privilege should not be there in the first place.
--
-- This migration closes all three.
-- =====================================================================

-- ---------------------------------------------------------------------
-- 1. The transition matrices are database-owned reference data
-- ---------------------------------------------------------------------
-- Only the SECURITY DEFINER functions read them (transition_job /
-- transition_booking). Nobody may write them, ever.
revoke all on public.job_transition_rules from anon, authenticated;
grant select on public.job_transition_rules to authenticated;

revoke all on public.booking_transition_rules from anon, authenticated;
grant select on public.booking_transition_rules to authenticated;

-- ---------------------------------------------------------------------
-- 2. Privileges that are not covered by Row Level Security
-- ---------------------------------------------------------------------
revoke truncate, references, trigger
  on all tables in schema public
  from anon, authenticated;

-- ---------------------------------------------------------------------
-- 3. `anon` must not be able to read private tables at all
-- ---------------------------------------------------------------------
-- Public catalogue data (service categories, approved professional
-- profiles, their services and areas, and public reviews) keeps its
-- `anon` access on purpose.
revoke select on table
  public.profiles,
  public.professional_services,
  public.service_areas,
  public.audit_log,
  public.verification_documents,
  public.notifications,
  public.device_tokens,
  public.push_outbox,
  public.job_requests,
  public.job_photos,
  public.job_status_events,
  public.job_matches,
  public.matching_queue,
  public.quotations,
  public.bookings,
  public.messages,
  public.reports,
  public.idempotency_keys
  from anon;

-- The same tables are still readable by a signed-in user; the RLS
-- policies decide which rows.
grant select on table
  public.profiles,
  public.professional_services,
  public.service_areas,
  public.audit_log,
  public.verification_documents,
  public.notifications,
  public.device_tokens,
  public.job_requests,
  public.job_photos,
  public.job_status_events,
  public.job_matches,
  public.quotations,
  public.bookings,
  public.messages,
  public.reports
  to authenticated;

-- The outbox and the idempotency table are service-role only: they are
-- written by the push edge function and by trusted server routes.
revoke all on public.push_outbox from anon, authenticated;
revoke all on public.idempotency_keys from anon, authenticated;

-- ---------------------------------------------------------------------
-- 4. Belt and braces: the transition matrices are not user tables
-- ---------------------------------------------------------------------
alter table public.job_transition_rules enable row level security;
alter table public.booking_transition_rules enable row level security;

drop policy if exists "job_transition_rules_read_authenticated"
  on public.job_transition_rules;
create policy "job_transition_rules_read_authenticated"
  on public.job_transition_rules
  for select
  to authenticated
  using (true);

drop policy if exists "booking_transition_rules_read_authenticated"
  on public.booking_transition_rules;
create policy "booking_transition_rules_read_authenticated"
  on public.booking_transition_rules
  for select
  to authenticated
  using (true);


-- ======================================================================
-- FILE: 20261020001400_message_views.sql
======================================================================
-- =====================================================================
-- FixLink Ethiopia - 015: message conversation views
-- =====================================================================
-- The dashboard needs two read models that do not exist as tables:
--
--   view_participant_conversations - one row per booking the caller
--     takes part in, with the last message and the other party.
--
--   view_unread_message_counts - one row per booking with the number of
--     messages the caller has not read yet.
--
-- Both views are owned by the database and filter on
-- public.current_profile_id() / public.current_professional_id(), so a
-- caller only ever sees their own conversations, even though the view
-- itself bypasses the Row Level Security of the underlying tables.
--
-- These views read `messages`, so they must be created after
-- 20261020000900_messages.sql.
-- =====================================================================

drop view if exists public.view_participant_conversations;
create view public.view_participant_conversations as
select
  b.id                     as booking_id,
  b.customer_id,
  b.professional_id,
  b.status                 as booking_status,
  b.scheduled_at,
  coalesce(p.full_name, 'Professional') as professional_name,
  coalesce(cp.full_name, '')            as customer_name,
  sc.name                  as service_category,
  jr.title                 as job_title,
  jr.area_name             as area_name,
  lm.body                  as last_message_body,
  lm.created_at            as last_message_at
from public.bookings b
join public.job_requests jr
  on jr.id = b.job_id
left join public.service_categories sc
  on sc.id = jr.category_id
left join public.professionals pr
  on pr.id = b.professional_id
left join public.profiles p
  on p.id = pr.profile_id
left join public.profiles cp
  on cp.id = b.customer_id
left join lateral (
  select m.body, m.created_at
  from public.messages m
  where m.booking_id = b.id
  order by m.created_at desc
  limit 1
) lm on true
where b.customer_id = public.current_profile_id()
   or b.professional_id = public.current_professional_id()
   or public.is_admin();

comment on view public.view_participant_conversations is
  'Bookings the caller takes part in, with the most recent message.';

drop view if exists public.view_unread_message_counts;
create view public.view_unread_message_counts as
select
  b.id as booking_id,
  count(m.id)::int as unread_count
from public.bookings b
left join public.messages m
  on m.booking_id = b.id
 and m.read_at is null
 and m.sender_id is distinct from public.current_profile_id()
where b.customer_id = public.current_profile_id()
   or b.professional_id = public.current_professional_id()
   or public.is_admin()
group by b.id;

comment on view public.view_unread_message_counts is
  'Unread message count per booking, for the caller only.';

revoke all on public.view_participant_conversations from anon;
revoke all on public.view_unread_message_counts from anon;
grant select on public.view_participant_conversations to authenticated;
grant select on public.view_unread_message_counts to authenticated;


-- ======================================================================
-- FILE: 20261020001500_privilege_tightening_and_insert_guards.sql
======================================================================
-- =====================================================================
-- FixLink Ethiopia - 016: privilege tightening and insert guards
-- =====================================================================
-- Follow-up to 20261020001300_lock_down_privileges.sql.
--
-- Two problems are left:
--
--   1. `anon` still holds INSERT/UPDATE/DELETE on several tables.
--      Row Level Security stops the rows, but the privilege itself is
--      wrong and must not be there.
--
--   2. `professionals` could be self-inserted by any signed-in user
--      with `verification_status = 'approved'`, because the guard
--      trigger only fired on UPDATE. The row would then look like an
--      approved professional to the matching algorithm and to the
--      public profile cards. The guard now covers INSERT as well.
--
-- The views were created AFTER the previous migration, so they also
-- need the write privileges taken away.
-- =====================================================================

-- ---------------------------------------------------------------------
-- 1. `anon` is a read-only role
-- ---------------------------------------------------------------------
do $$
declare
  r record;
begin
  for r in
    select c.relname
    from pg_class c
    join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'public' and c.relkind in ('r', 'v', 'p')
  loop
    execute format(
      'revoke insert, update, delete, truncate on table public.%I from anon',
      r.relname
    );
  end loop;
end
$$;

-- ---------------------------------------------------------------------
-- 2. The audit trail is written by SECURITY DEFINER functions only
-- ---------------------------------------------------------------------
revoke insert, update, delete, truncate on public.audit_log from anon, authenticated;

-- ---------------------------------------------------------------------
-- 3. Administrators may edit the single matching_config row, never
--    create or destroy one
-- ---------------------------------------------------------------------
revoke insert, delete, truncate on public.matching_config from anon, authenticated;

-- ---------------------------------------------------------------------
-- 4. The conversation views are read models
-- ---------------------------------------------------------------------
revoke insert, update, delete, truncate
  on public.view_participant_conversations from anon, authenticated;
revoke insert, update, delete, truncate
  on public.view_unread_message_counts from anon, authenticated;
grant select on public.view_participant_conversations to authenticated;
grant select on public.view_unread_message_counts to authenticated;

-- ---------------------------------------------------------------------
-- 5. A professional row is created by public.start_as_professional()
--    only, so nobody can hand themselves an approved profile
-- ---------------------------------------------------------------------
revoke insert on public.professionals from anon, authenticated;

-- The guard now covers INSERT as well as UPDATE. On INSERT the
-- verification status and the rating counters are forced back to their
-- defaults, whatever the client sent.
create or replace function public.protect_professional_insert()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  -- Inside a SECURITY DEFINER function (start_as_professional) the
  -- statement runs as the table owner: trusted, nothing to force.
  if current_user in ('postgres', 'supabase_admin') then
    return new;
  end if;

  new.verification_status := 'pending';
  new.average_rating := null;
  new.total_reviews := 0;
  new.completed_jobs := 0;
  new.quotation_response_rate := null;
  return new;
end;
$$;

drop trigger if exists professionals_protect_insert on public.professionals;
create trigger professionals_protect_insert
  before insert on public.professionals
  for each row execute function public.protect_professional_insert();

-- ---------------------------------------------------------------------
-- 6. A verification document is uploaded unreviewed
-- ---------------------------------------------------------------------
-- A professional must not be able to mark their own document as
-- reviewed; only an administrator (public.set_verification_status)
-- may stamp it.
create or replace function public.protect_verification_document_insert()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if current_user in ('postgres', 'supabase_admin') or public.is_admin() then
    return new;
  end if;

  new.reviewed_at := null;
  new.reviewed_by := null;
  new.review_note := null;
  return new;
end;
$$;

drop trigger if exists verification_documents_protect_insert
  on public.verification_documents;
create trigger verification_documents_protect_insert
  before insert on public.verification_documents
  for each row execute function public.protect_verification_document_insert();


-- ======================================================================
-- FILE: 20261020001600_professional_locations_view.sql
======================================================================
-- =====================================================================
-- FixLink Ethiopia - 017: public professional locations
-- =====================================================================
-- The map and the public profile cards need the sub-city of a
-- professional and the categories they offer, but `professionals.base_location`
-- is a `geography` point, which PostgREST cannot return in a usable form.
--
-- This view projects it into plain columns:
--
--   sub_city_code / base_area_name   the sub-city the professional is in
--   categories                       the offered categories as JSON
--
-- Only APPROVED professionals appear: this is the public directory, so it
-- is readable without an account (`anon`). Everything else stays behind
-- the Row Level Security of the underlying tables.
-- =====================================================================

drop view if exists public.professional_locations;
create view public.professional_locations as
select
  pr.id as professional_id,
  pr.profile_id,
  p.full_name,
  p.avatar_url,
  pr.sub_city_code,
  pr.base_area_name,
  pr.verification_status,
  pr.accepts_requests,
  pr.service_radius_km,
  pr.years_of_experience,
  pr.average_rating,
  pr.total_reviews,
  pr.completed_jobs,
  (
    select json_agg(
      json_build_object(
        'id', ps.category_id,
        'slug', sc.slug,
        'name', sc.name,
        'name_am', sc.name_am,
        'name_om', sc.name_om
      )
      order by sc.sort_order
    )
    from public.professional_services ps
    join public.service_categories sc on sc.id = ps.category_id
    where ps.professional_id = pr.id
  ) as categories
from public.professionals pr
join public.profiles p on p.id = pr.profile_id
where pr.verification_status = 'approved';

comment on view public.professional_locations is
  'Public directory of approved professionals: sub-city, categories and rating.';

revoke all on public.professional_locations from anon;
grant select on public.professional_locations to anon, authenticated;


-- ======================================================================
-- FILE: 20261020001700_admin_professional_availability.sql
======================================================================
-- =====================================================================
-- FixLink Ethiopia - 018: administrator control of professional availability
-- =====================================================================
-- `public.update_professional_profile()` always writes the CALLER's own
-- professional row, which is the right behaviour for a professional editing
-- their own profile — but it means an administrator cannot pause a
-- professional from the admin dashboard.
--
-- This function is the administrator's counterpart: it writes another
-- professional's availability toggle and nothing else. It is SECURITY
-- DEFINER so it can write the protected column, and it refuses anyone who
-- is not an active administrator.
-- =====================================================================

create or replace function public.set_professional_availability(
  p_professional_id uuid,
  p_accepts_requests boolean
)
returns public.professionals
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor uuid := public.current_profile_id();
  v_professional public.professionals;
begin
  if not public.is_admin() then
    raise exception 'admin_required' using errcode = '42501';
  end if;

  select * into v_professional
  from public.professionals
  where id = p_professional_id
  for update;

  if not found then
    raise exception 'professional_not_found' using errcode = 'P0002';
  end if;

  update public.professionals
     set accepts_requests = coalesce(p_accepts_requests, accepts_requests)
   where id = p_professional_id
   returning * into v_professional;

  insert into public.audit_log (
    actor_id, actor_role, action, entity_type, entity_id, details
  )
  values (
    v_actor,
    'admin',
    'professional.availability_' || (case when p_accepts_requests then 'enabled' else 'paused' end),
    'professional',
    p_professional_id,
    jsonb_build_object('accepts_requests', p_accepts_requests)
  );

  return v_professional;
end;
$$;

comment on function public.set_professional_availability(uuid, boolean) is
  'Administrator only: pause or resume a professional from the admin dashboard.';

revoke all on function public.set_professional_availability(uuid, boolean) from anon;
grant execute on function public.set_professional_availability(uuid, boolean) to authenticated;


-- ======================================================================
-- FILE: 20261020001800_fix_response_rate_trigger.sql
======================================================================
-- =====================================================================
-- FixLink Ethiopia - 019: fix the quotation response rate trigger
-- =====================================================================
-- `refresh_professional_response_rate()` updated
-- `professionals.quotation_response_rate` with `sub.rate`, but the
-- subquery only produces `total` and `responded`:
--
--   ERROR: column sub.rate does not exist
--
-- The trigger `job_matches_refresh_rate` fires on every insert into
-- `job_matches`, so matching a professional with a request failed
-- outright. The rate is the share of notifications that led to a
-- quotation.
-- =====================================================================

create or replace function public.refresh_professional_response_rate()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  update public.professionals p
     set quotation_response_rate = sub.responded / sub.total
    from (
      select
        count(*)::numeric as total,
        count(*) filter (where m.response_status in ('viewed', 'quoted'))::numeric as responded
      from public.job_matches m
      where m.professional_id = new.professional_id
    ) sub
    where p.id = new.professional_id
      and sub.total > 0
      and sub.responded / sub.total <> coalesce(p.quotation_response_rate, -1);

  return new;
end;
$$;

comment on function public.refresh_professional_response_rate() is
  'Keeps professionals.quotation_response_rate in step with their matches.';


-- ======================================================================
-- FILE: 20261020001900_notification_emailed_at.sql
======================================================================
-- =====================================================================
-- FixLink Ethiopia - 020: track the e-mail delivery of the notifications
-- =====================================================================
-- The database writes the in-app notifications; the server delivers them
-- by e-mail (Resend). This column records when a notification was sent,
-- so a delivery can be retried without sending the same e-mail twice.
-- =====================================================================

alter table public.notifications
  add column if not exists emailed_at timestamptz;

comment on column public.notifications.emailed_at is
  'When the notification was delivered by e-mail. NULL means not delivered yet.';


-- ======================================================================
-- FILE: 20261020002000_fix_rls_recursion.sql
======================================================================
-- =====================================================================
-- FixLink Ethiopia — 021: break the Row Level Security recursion
-- =====================================================================
-- THE BUG
-- -------
-- Two policies referenced each other, and PostgreSQL refuses to evaluate
-- them:
--
--   job_requests_select_participants   (on job_requests)
--     -> exists (select 1 from public.job_matches ...)
--
--   job_matches_select_participants   (on job_matches)
--     -> exists (select 1 from public.job_requests ...)
--
-- Reading a job request made PostgreSQL evaluate the policy on
-- `job_matches`, which made it evaluate the policy on `job_requests`
-- again. PostgreSQL detects the cycle and aborts the whole query:
--
--   ERROR: infinite recursion detected in policy for relation "job_requests"
--
-- It broke every screen that lists requests, including the administrator
-- review screen, because the policy expression is evaluated for every row
-- regardless of the caller.
--
-- THE FIX
-- -------
-- The cross-table lookups move into SECURITY DEFINER helper functions.
-- A SECURITY DEFINER function owned by the table owner reads the table
-- WITHOUT its Row Level Security policies, so the policy on `job_matches`
-- is never evaluated from inside the policy on `job_requests` — and the
-- cycle disappears.
--
-- The helpers are safe to expose, because they take no identity from
-- their arguments: they always answer the question "may THIS caller see
-- this job?", and the caller is resolved from the JWT.
-- =====================================================================

-- ---------------------------------------------------------------------
-- The helpers
-- ---------------------------------------------------------------------
-- May the caller see this job because they own it?
create or replace function public.is_job_owner(p_job_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.job_requests j
    where j.id = p_job_id
      and j.customer_id = public.current_profile_id()
  );
$$;

comment on function public.is_job_owner(uuid) is
  'True when the caller is the customer who created the job.';

-- May the caller see this job because they were notified about it?
create or replace function public.is_matched_to_job(p_job_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.job_matches m
    where m.job_id = p_job_id
      and m.professional_id = public.current_professional_id()
  );
$$;

comment on function public.is_matched_to_job(uuid) is
  'True when the calling professional was matched to the job.';

-- May the caller see this job because they have a booking for it?
create or replace function public.has_professional_booking(p_job_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.bookings b
    where b.job_id = p_job_id
      and b.professional_id = public.current_professional_id()
  );
$$;

comment on function public.has_professional_booking(uuid) is
  'True when the calling professional has a booking for the job.';

-- The complete rule: who may see a job request.
create or replace function public.can_view_job(p_job_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select
    public.is_admin()
    or public.is_job_owner(p_job_id)
    or public.is_matched_to_job(p_job_id)
    or public.has_professional_booking(p_job_id);
$$;

comment on function public.can_view_job(uuid) is
  'True when the caller may read the job: the owner, an administrator, a matched professional, or a professional with a booking.';

-- The same rule, for a job id that arrives as text (the storage paths
-- carry the job id as a folder name, and a folder name is not
-- guaranteed to be a uuid — casting it could raise an error instead of
-- simply saying "not visible").
create or replace function public.is_job_visible_to_matched_professional(
  p_job_id_text text
)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.job_requests j
    join public.job_matches m on m.job_id = j.id
    where j.id::text = p_job_id_text
      and m.professional_id = public.current_professional_id()
  );
$$;

comment on function public.is_job_visible_to_matched_professional(text) is
  'True when the calling professional was matched to the job whose id is given as text.';

-- ---------------------------------------------------------------------
-- The policies, rewritten with the helpers
-- ---------------------------------------------------------------------
drop policy if exists "job_requests_select_participants" on public.job_requests;
create policy "job_requests_select_participants"
  on public.job_requests
  for select
  to authenticated
  using (public.can_view_job(job_requests.id));

drop policy if exists "job_matches_select_participants" on public.job_matches;
create policy "job_matches_select_participants"
  on public.job_matches
  for select
  to authenticated
  using (
    professional_id = public.current_professional_id()
    or public.is_admin()
    or public.is_job_owner(job_matches.job_id)
  );

drop policy if exists "job_photos_select_participants" on public.job_photos;
create policy "job_photos_select_participants"
  on public.job_photos
  for select
  to authenticated
  using (public.can_view_job(job_photos.job_id));

drop policy if exists "job_photos_insert_owner" on public.job_photos;
create policy "job_photos_insert_owner"
  on public.job_photos
  for insert
  to authenticated
  with check (public.is_job_owner(job_photos.job_id));

drop policy if exists "job_photos_delete_owner" on public.job_photos;
create policy "job_photos_delete_owner"
  on public.job_photos
  for delete
  to authenticated
  using (public.is_job_owner(job_photos.job_id));

drop policy if exists "job_status_events_select_participants" on public.job_status_events;
create policy "job_status_events_select_participants"
  on public.job_status_events
  for select
  to authenticated
  using (public.can_view_job(job_status_events.job_id));

drop policy if exists "quotations_select_participants" on public.quotations;
create policy "quotations_select_participants"
  on public.quotations
  for select
  to authenticated
  using (
    professional_id = public.current_professional_id()
    or public.is_admin()
    or public.is_job_owner(quotations.job_id)
  );

-- ---------------------------------------------------------------------
-- The helpers are safe to call from a policy, so they need EXECUTE.
-- They are granted to the application roles like every other helper.
-- ---------------------------------------------------------------------
grant execute on function public.is_job_owner(uuid) to authenticated;
grant execute on function public.is_matched_to_job(uuid) to authenticated;
grant execute on function public.has_professional_booking(uuid) to authenticated;
grant execute on function public.can_view_job(uuid) to authenticated;
grant execute on function public.is_job_visible_to_matched_professional(text) to authenticated;

-- ---------------------------------------------------------------------
-- The storage policy for the job photos
-- ---------------------------------------------------------------------
-- It joined `job_requests` and `job_matches` directly, which made
-- PostgreSQL evaluate the policies of both tables for every object. The
-- helper answers the same question without touching the policies.
drop policy if exists "job_photos_read_participants" on storage.objects;
create policy "job_photos_read_participants"
  on storage.objects
  for select
  to authenticated
  using (
    bucket_id = 'job-photos'
    and (
      (storage.foldername(name))[1] = public.current_profile_id()::text
      or public.is_admin()
      or public.is_job_visible_to_matched_professional(
        (storage.foldername(name))[2]
      )
    )
  );


-- ======================================================================
-- FILE: 20261020002100_matching_queue_functions.sql
======================================================================
-- =====================================================================
-- FixLink Ethiopia — 022: the matching queue, for the background worker
-- =====================================================================
-- `public.request_matching()` puts a request into `public.matching_queue`,
-- and `public.expand_matching()` is granted to `service_role` only — a
-- browser must never widen the search radius on its own.
--
-- That means a background worker has to drive the queue. It needs three
-- operations, and they have to be safe when two workers run at the same
-- time:
--
--   claim_matching_queue()   take the rows that are due
--   complete_matching_queue() the request was matched
--   fail_matching_queue()    the request could not be matched
--
-- The claim uses `for update skip locked`, so a second worker skips the
-- rows the first one is holding instead of waiting for them.
-- =====================================================================

-- ---------------------------------------------------------------------
-- Claim the rows that are due
-- ---------------------------------------------------------------------
create or replace function public.claim_matching_queue(p_limit int default 20)
returns setof public.matching_queue
language plpgsql
security definer
set search_path = public
as $$
declare
  v_row public.matching_queue;
begin
  for v_row in
    select q.*
    from public.matching_queue q
    where q.status = 'pending'
      and q.available_at <= now()
    order by q.available_at
    limit greatest(1, least(coalesce(p_limit, 20), 200))
    for update skip locked
  loop
    -- The row is locked by this transaction: mark it as being worked on
    -- so a second worker cannot pick it up.
    update public.matching_queue
       set status = 'processing',
           attempts = attempts + 1
     where id = v_row.id
    returning * into v_row;

    return next v_row;
  end loop;

  return;
end;
$$;

comment on function public.claim_matching_queue(int) is
  'Claims the matching queue rows that are due. Uses FOR UPDATE SKIP LOCKED so two workers never take the same row.';

-- ---------------------------------------------------------------------
-- The request was matched
-- ---------------------------------------------------------------------
create or replace function public.complete_matching_queue(
  p_id uuid,
  p_notified int default 0
)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  update public.matching_queue
     set status = 'done',
         processed_at = now(),
         last_error = null
   where id = p_id;
end;
$$;

comment on function public.complete_matching_queue(uuid, int) is
  'Marks a matching queue row as done.';

-- ---------------------------------------------------------------------
-- The request could not be matched
-- ---------------------------------------------------------------------
-- A row that failed is tried again later, up to five times. After that
-- it is marked as failed and an administrator can look at it.
create or replace function public.fail_matching_queue(
  p_id uuid,
  p_error text default null
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_attempts integer;
begin
  update public.matching_queue
     set status = case when attempts >= 5 then 'failed' else 'pending' end,
         available_at = now() + interval '2 minutes',
         last_error = left(coalesce(p_error, ''), 500)
   where id = p_id
  returning attempts into v_attempts;
end;
$$;

comment on function public.fail_matching_queue(uuid, text) is
  'Records a matching failure. The row is retried up to five times, then it is marked as failed.';

-- ---------------------------------------------------------------------
-- The worker is the only caller
-- ---------------------------------------------------------------------
grant execute on function public.claim_matching_queue(int) to service_role;
grant execute on function public.complete_matching_queue(uuid, int) to service_role;
grant execute on function public.fail_matching_queue(uuid, text) to service_role;

-- The worker also calls these two.
grant execute on function public.match_job(uuid, int, numeric, int) to service_role;
grant execute on function public.expand_matching(uuid) to service_role;


-- ======================================================================
-- FILE: 20261020002200_push_outbox_functions.sql
======================================================================
-- =====================================================================
-- FixLink Ethiopia — 023: the push outbox, for the push dispatcher
-- =====================================================================
-- `public.notify()` writes an in-app notification AND enqueues a row in
-- `public.push_outbox`. The in-app notification is the source of truth;
-- the push is only a nudge, so a failure to deliver it must never lose
-- anything.
--
-- The dispatcher (supabase/functions/push-dispatcher) needs the same
-- three operations as the matching worker, with the same
-- `for update skip locked` guarantee, so two dispatchers never send the
-- same push twice.
-- =====================================================================

-- ---------------------------------------------------------------------
-- Claim the rows that are due
-- ---------------------------------------------------------------------
create or replace function public.claim_push_outbox(p_limit int default 20)
returns setof public.push_outbox
language plpgsql
security definer
set search_path = public
as $$
declare
  v_row public.push_outbox;
begin
  for v_row in
    select o.*
    from public.push_outbox o
    where o.status = 'pending'
    order by o.created_at
    limit greatest(1, least(coalesce(p_limit, 20), 200))
    for update skip locked
  loop
    update public.push_outbox
       set status = 'pending',
           attempts = attempts + 1
     where id = v_row.id
    returning * into v_row;

    return next v_row;
  end loop;

  return;
end;
$$;

comment on function public.claim_push_outbox(int) is
  'Claims the pending push outbox rows. Uses FOR UPDATE SKIP LOCKED so two dispatchers never send the same push.';

-- ---------------------------------------------------------------------
-- The push was delivered
-- ---------------------------------------------------------------------
create or replace function public.complete_push_outbox(p_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  update public.push_outbox
     set status = 'sent',
         sent_at = now(),
         last_error = null
   where id = p_id;
end;
$$;

comment on function public.complete_push_outbox(uuid) is
  'Marks a push outbox row as sent.';

-- ---------------------------------------------------------------------
-- The push could not be delivered
-- ---------------------------------------------------------------------
-- The in-app notification is still there, so the row is simply marked as
-- failed after five attempts. It is never retried forever.
create or replace function public.fail_push_outbox(
  p_id uuid,
  p_error text default null
)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  update public.push_outbox
     set status = case when attempts >= 5 then 'failed' else 'pending' end,
         last_error = left(coalesce(p_error, ''), 500)
   where id = p_id;
end;
$$;

comment on function public.fail_push_outbox(uuid, text) is
  'Records a push failure. The row is retried up to five times, then it is marked as failed.';

-- ---------------------------------------------------------------------
-- The tokens of a user, for the dispatcher
-- ---------------------------------------------------------------------
create or replace function public.device_tokens_of(p_user_id uuid)
returns table (token text, platform public.device_platform)
language sql
stable
security definer
set search_path = public
as $$
  select d.token, d.platform
  from public.device_tokens d
  where d.user_id = p_user_id;
$$;

comment on function public.device_tokens_of(uuid) is
  'The push tokens of a user. Only the dispatcher may call it.';

-- ---------------------------------------------------------------------
-- The dispatcher is the only caller
-- ---------------------------------------------------------------------
grant execute on function public.claim_push_outbox(int) to service_role;
grant execute on function public.complete_push_outbox(uuid) to service_role;
grant execute on function public.fail_push_outbox(uuid, text) to service_role;
grant execute on function public.device_tokens_of(uuid) to service_role;


-- ======================================================================
-- FILE: 20261020002400_sub_city_columns_and_functions.sql
======================================================================
-- =====================================================================
-- FixLink Ethiopia - 024: the sub-city columns and the functions
-- =====================================================================
-- The tables of the platform are located by the sub-city of the Dire Dawa
-- administration (see 20261020000250_sub_cities.sql).
--
-- The columns and the functions were introduced together with the table,
-- but they are applied here as well: the database that already runs the
-- first migrations of the project gets the sub-city support without
-- touching them.
--
-- A request and a professional carry the code of their sub-city; the name
-- and the point of the map are copied from the reference table, so they
-- are never collected from a visitor.
-- =====================================================================

-- ---------------------------------------------------------------------
-- 1. The columns
-- ---------------------------------------------------------------------
alter table public.job_requests
  add column if not exists sub_city_code text;

alter table public.professionals
  add column if not exists sub_city_code text;

do $$
begin
  if not exists (
    select 1 from pg_constraint where conname = 'job_requests_sub_city_code_fkey'
  ) then
    alter table public.job_requests
      add constraint job_requests_sub_city_code_fkey
      foreign key (sub_city_code) references public.sub_cities (code);
  end if;

  if not exists (
    select 1 from pg_constraint where conname = 'professionals_sub_city_code_fkey'
  ) then
    alter table public.professionals
      add constraint professionals_sub_city_code_fkey
      foreign key (sub_city_code) references public.sub_cities (code);
  end if;
end
$$;

-- The rows that already exist point at the sub-city of their area name,
-- when there is one. The others stay empty until they are filled in.
update public.job_requests jr
   set sub_city_code = sc.code
  from public.sub_cities sc
 where jr.sub_city_code is null
   and lower(sc.name) = lower(jr.area_name);

update public.professionals pr
   set sub_city_code = sc.code
  from public.sub_cities sc
 where pr.sub_city_code is null
   and lower(sc.name) = lower(pr.base_area_name);

-- ---------------------------------------------------------------------
-- 2. The request is created from the sub-city
-- ---------------------------------------------------------------------
drop function if exists public.create_job_request(
  uuid, text, text, text, double precision, double precision,
  public.location_source, public.job_priority, text
);

create or replace function public.create_job_request(
  p_category_id uuid,
  p_title text,
  p_description text,
  p_sub_city_code text,
  p_priority public.job_priority default 'normal',
  p_idempotency_key text default null
)
returns public.job_requests
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor uuid := public.current_profile_id();
  v_existing public.job_requests;
  v_job public.job_requests;
begin
  if v_actor is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;

  -- Idempotent retry: return the request that was already created.
  if p_idempotency_key is not null and length(btrim(p_idempotency_key)) >= 8 then
    select * into v_existing
    from public.job_requests
    where customer_id = v_actor and idempotency_key = p_idempotency_key;

    if found then
      return v_existing;
    end if;
  end if;

  if not exists (
    select 1 from public.service_categories
    where id = p_category_id and is_active
  ) then
    raise exception 'inactive_or_unknown_category' using errcode = '22023';
  end if;

  -- The location of a request is the sub-city it is in. The name and the
  -- point come from the reference table, never from the client. An unknown
  -- code inserts no row at all.
  insert into public.job_requests (
    customer_id, category_id, title, description, priority, status,
    sub_city_code, area_name, location, idempotency_key, expires_at
  )
  select
    v_actor,
    p_category_id,
    btrim(p_title),
    btrim(p_description),
    coalesce(p_priority, 'normal'),
    'open',
    sc.code,
    sc.name,
    sc.location,
    nullif(btrim(coalesce(p_idempotency_key, '')), ''),
    now() + interval '72 hours'
  from public.sub_cities sc
  where sc.code = p_sub_city_code
  returning * into v_job;

  if v_job.id is null then
    raise exception 'unknown_sub_city' using errcode = '22023';
  end if;

  insert into public.job_status_events (
    job_id, actor_id, actor_role, from_status, to_status, note
  )
  values (v_job.id, v_actor, 'customer', 'open', 'open', 'Request created');

  return v_job;
end;
$$;

comment on function public.create_job_request(uuid, text, text, text, public.job_priority, text) is
  'Create a service request for the signed-in customer. The sub-city gives the area and the point of the map.';

-- ---------------------------------------------------------------------
-- 3. The request can be moved to another sub-city
-- ---------------------------------------------------------------------
drop function if exists public.update_job_request(
  uuid, text, text, text, double precision, double precision, public.job_priority
);

create or replace function public.update_job_request(
  p_job_id uuid,
  p_title text default null,
  p_description text default null,
  p_sub_city_code text default null,
  p_priority public.job_priority default null
)
returns public.job_requests
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor uuid := public.current_profile_id();
  v_job public.job_requests;
begin
  if v_actor is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;

  select * into v_job
  from public.job_requests
  where id = p_job_id
  for update;

  if not found then
    raise exception 'job_not_found' using errcode = 'P0002';
  end if;

  if v_job.customer_id <> v_actor and not public.is_admin() then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if v_job.status not in ('open', 'matching', 'quoted') then
    raise exception 'job_not_editable' using errcode = '22023';
  end if;

  -- The sub-city is only changed when the client sends a known one.
  if p_sub_city_code is not null
     and not exists (
       select 1 from public.sub_cities where code = p_sub_city_code
     ) then
    raise exception 'unknown_sub_city' using errcode = '22023';
  end if;

  update public.job_requests
     set title = coalesce(nullif(btrim(coalesce(p_title, '')), ''), title),
         description = coalesce(nullif(btrim(coalesce(p_description, '')), ''), description),
         sub_city_code = coalesce(p_sub_city_code, sub_city_code),
         area_name = coalesce(
           (select sc.name from public.sub_cities sc where sc.code = p_sub_city_code),
           area_name
         ),
         location = coalesce(
           (select sc.location from public.sub_cities sc where sc.code = p_sub_city_code),
           location
         ),
         priority = coalesce(p_priority, priority)
   where id = p_job_id
   returning * into v_job;

  return v_job;
end;
$$;

comment on function public.update_job_request(uuid, text, text, text, public.job_priority) is
  'Edit a request that is not booked yet. The sub-city gives the area and the point of the map.';

-- ---------------------------------------------------------------------
-- 4. The professional works in a sub-city
-- ---------------------------------------------------------------------
drop function if exists public.update_professional_profile(
  text, integer, boolean, numeric, text, double precision, double precision
);

create or replace function public.update_professional_profile(
  p_bio text default null,
  p_years_of_experience int default null,
  p_accepts_requests boolean default null,
  p_service_radius_km numeric default null,
  p_base_sub_city_code text default null
)
returns public.professionals
language plpgsql
security definer
set search_path = public
as $$
declare
  v_professional_id uuid := public.current_professional_id();
  v_row public.professionals;
begin
  if v_professional_id is null then
    raise exception 'not_a_professional' using errcode = '42501';
  end if;

  -- The base of a professional is a sub-city: the name and the point come
  -- from the reference table, never from the client.
  if p_base_sub_city_code is not null
     and not exists (
       select 1 from public.sub_cities where code = p_base_sub_city_code
     ) then
    raise exception 'unknown_sub_city' using errcode = '22023';
  end if;

  update public.professionals
     set bio = coalesce(p_bio, bio),
         years_of_experience = coalesce(
           p_years_of_experience,
           years_of_experience
         ),
         accepts_requests = coalesce(p_accepts_requests, accepts_requests),
         service_radius_km = coalesce(
           greatest(1, least(100, p_service_radius_km)),
           service_radius_km
         ),
         sub_city_code = coalesce(p_base_sub_city_code, sub_city_code),
         base_area_name = coalesce(
           (select sc.name from public.sub_cities sc where sc.code = p_base_sub_city_code),
           base_area_name
         ),
         base_location = coalesce(
           (select sc.location from public.sub_cities sc where sc.code = p_base_sub_city_code),
           base_location
         )
   where id = v_professional_id
   returning * into v_row;

  return v_row;
end;
$$;

comment on function public.update_professional_profile(text, integer, boolean, numeric, text) is
  'Update the fields a professional may change themselves. The base sub-city gives the area and the point of the map.';

-- ---------------------------------------------------------------------
-- 5. The public directory shows the sub-city
-- ---------------------------------------------------------------------
-- The view is dropped and created again: a column was added to it, and
-- `create or replace view` cannot change the columns of a view.
drop view if exists public.professional_locations;

create view public.professional_locations as
select
  pr.id as professional_id,
  pr.profile_id,
  p.full_name,
  p.avatar_url,
  pr.base_area_name,
  pr.sub_city_code,
  pr.verification_status,
  pr.accepts_requests,
  pr.service_radius_km,
  pr.years_of_experience,
  pr.average_rating,
  pr.total_reviews,
  pr.completed_jobs,
  case
    when pr.base_location is not null
      then extensions.st_y(pr.base_location::extensions.geometry)
  end as latitude,
  case
    when pr.base_location is not null
      then extensions.st_x(pr.base_location::extensions.geometry)
  end as longitude,
  (
    select json_agg(
      json_build_object(
        'id', ps.category_id,
        'slug', sc.slug,
        'name', sc.name,
        'name_am', sc.name_am,
        'name_om', sc.name_om
      )
      order by sc.sort_order
    )
    from public.professional_services ps
    join public.service_categories sc on sc.id = ps.category_id
    where ps.professional_id = pr.id
  ) as categories
from public.professionals pr
join public.profiles p on p.id = pr.profile_id
where pr.verification_status = 'approved';

revoke all on public.professional_locations from anon;
grant select on public.professional_locations to anon, authenticated;


-- ======================================================================
-- FILE: 20261020002500_clerk_identity.sql
======================================================================
-- =====================================================================
-- FixLink Ethiopia — 025: the Clerk identity
--
-- CLERK is the only authentication system of the platform. The account
-- lives in Clerk (`user_2abc...`), the session lives in the cookie the
-- Clerk SDK manages, and the Clerk session token is sent to PostgREST as
-- `Authorization: Bearer <token>` (the JWT bridge).
--
-- PostgREST exposes the decoded claims through `request.jwt.claims`, so
-- the database resolves the caller from the `sub` claim — which is the
-- CLERK user id. That id is a TEXT (`user_...`), not a uuid: the previous
-- migration (002) was written for Supabase Auth, where the `sub` claim was
-- the uuid of `auth.users`. This migration corrects that:
--
--   * `profiles.clerk_user_id` (text) becomes the canonical external
--     identity, exactly as `supabase/README.md` documents it;
--   * the identity helpers read the `sub` claim as text;
--   * `ensure_profile()` also accepts the e-mail address, because a Clerk
--     session token does not carry one by default (the address is added by
--     a Clerk JWT template or sent by the client);
--   * two service-role-only functions are added for the Clerk webhook, so
--     the platform can synchronise an account without a signed-in user.
--
-- NOTHING IS DROPPED HERE: no table, no column and no earlier migration
-- disappears. The old `profiles.auth_user_id` column stays (it is simply
-- not the identity any more), and the rows that already have one keep it.
--
-- The Row Level Security design is NOT changed: the policies keep asking
-- `current_profile_id()`, `is_admin()` and `is_active_account()`, and those
-- functions keep resolving the caller from the token. Only the shape of
-- the identity changed.
--
-- A profile that has no `clerk_user_id` yet (a legacy row, or a demo row
-- created by `scripts/seed-demo.mjs`) is ADOPTED by the first Clerk sign-in
-- with the same e-mail address — so signing up never creates a second
-- profile for the same person.
-- =====================================================================

-- ---------------------------------------------------------------------
-- 1. The Clerk user id column
-- ---------------------------------------------------------------------
alter table public.profiles
  add column if not exists clerk_user_id text;

comment on column public.profiles.clerk_user_id is
  'The Clerk user id (user_...). The single source of identity. NULL until the account signs in for the first time.';

-- The e-mail address of the account is a COPY: it is written by
-- `ensure_profile()` and by the webhook of Clerk, and it is the only
-- address the platform can mail. The column is created here as well, so
-- this migration also applies to a database whose `profiles` table was
-- created without it.
alter table public.profiles
  add column if not exists email text;

comment on column public.profiles.email is
  'A copy of the e-mail address of the Clerk account. Synced by ensure_profile() and by the webhook of Clerk.';

-- The rows that already have an identity keep it: the uuid of the old
-- Supabase Auth account becomes the (text) external id.
--
-- The block is guarded: a database that never had the old column (a
-- project that started with Clerk) simply has nothing to convert.
do $$
begin
  if exists (
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = 'profiles'
      and column_name = 'auth_user_id'
  ) then
    update public.profiles
       set clerk_user_id = auth_user_id::text
     where clerk_user_id is null
       and auth_user_id is not null;
  end if;
end;
$$;

create unique index if not exists profiles_clerk_user_id_key
  on public.profiles (clerk_user_id);

create index if not exists profiles_clerk_user_id_idx
  on public.profiles (clerk_user_id);

create index if not exists profiles_email_idx
  on public.profiles (lower(email));

-- ---------------------------------------------------------------------
-- 2. The identity helpers
-- ---------------------------------------------------------------------
-- The Clerk user id of the caller, or NULL when nobody is signed in.
--
-- The `sub` claim is read from `request.jwt.claim.sub` (set by PostgREST)
-- with a fallback to the full `request.jwt.claims` document. The value is
-- TEXT: a Clerk user id is `user_...`, and it must never be cast to a
-- uuid.
create or replace function public.current_clerk_user_id()
returns text
language sql
stable
as $$
  select nullif(
    coalesce(
      nullif(current_setting('request.jwt.claim.sub', true), ''),
      (nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'sub')
    ),
    ''
  );
$$;

comment on function public.current_clerk_user_id() is
  'Clerk user id of the caller (request.jwt.claims.sub). NULL when signed out.';

-- The e-mail address of the caller, taken from the JWT `email` claim.
-- Only present when the Clerk instance adds it to the session token.
create or replace function public.current_auth_email()
returns text
language sql
stable
as $$
  select nullif(
    (nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'email'),
    ''
  );
$$;

comment on function public.current_auth_email() is
  'E-mail address of the caller from the JWT email claim. NULL when absent.';

-- The profiles.id (UUID) of the caller, or NULL when signed out.
-- SECURITY DEFINER so that reading `profiles` from inside a profiles
-- RLS policy does not recurse infinitely.
create or replace function public.current_profile_id()
returns uuid
language sql
stable
security definer
set search_path = public
as $$
  select p.id
  from public.profiles p
  where p.clerk_user_id = public.current_clerk_user_id()
  limit 1;
$$;

comment on function public.current_profile_id() is
  'profiles.id of the signed-in user, or NULL when signed out.';

-- The profiles.role of the caller, or NULL when signed out.
create or replace function public.current_user_role()
returns public.user_role
language sql
stable
security definer
set search_path = public
as $$
  select p.role
  from public.profiles p
  where p.clerk_user_id = public.current_clerk_user_id()
  limit 1;
$$;

comment on function public.current_user_role() is
  'profiles.role of the signed-in user, or NULL when signed out.';

-- True only for an ACTIVE administrator.
create or replace function public.is_admin()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.profiles p
    where p.clerk_user_id = public.current_clerk_user_id()
      and p.role = 'admin'
      and p.account_status = 'active'
  );
$$;

comment on function public.is_admin() is
  'True when the caller is an active administrator. Used by every privileged policy.';

-- True when the caller owns an active (not suspended / not closed) account.
create or replace function public.is_active_account()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.profiles p
    where p.clerk_user_id = public.current_clerk_user_id()
      and p.account_status = 'active'
  );
$$;

comment on function public.is_active_account() is
  'True when the caller owns an active account.';

-- The old helper is gone: the identity is the Clerk user id now.
drop function if exists public.current_auth_user_id();

-- ---------------------------------------------------------------------
-- 3. ensure_profile(): create or refresh the profile of the caller
-- ---------------------------------------------------------------------
-- SECURITY DEFINER: the client may not insert into `profiles` directly
-- (that would allow choosing `role`, `account_status`, or another
-- user's `clerk_user_id`). This function fixes all of those server-side.
--
-- It is IDEMPOTENT: calling it twice never creates a second profile.
--
-- `p_email` is optional: a Clerk session token does not carry the address
-- by default, so the client (which knows it) or the Clerk webhook passes
-- it explicitly.
drop function if exists public.ensure_profile(text, text, text);

create or replace function public.ensure_profile(
  p_full_name text default null,
  p_phone text default null,
  p_avatar_url text default null,
  p_email text default null
)
returns public.profiles
language plpgsql
security definer
set search_path = public
as $$
declare
  v_clerk_user_id text := public.current_clerk_user_id();
  v_email text := coalesce(
    nullif(btrim(coalesce(p_email, '')), ''),
    nullif(btrim(coalesce(public.current_auth_email(), '')), '')
  );
  v_profile public.profiles;
  v_name text := nullif(btrim(coalesce(p_full_name, '')), '');
begin
  if v_clerk_user_id is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;

  select * into v_profile
  from public.profiles
  where clerk_user_id = v_clerk_user_id;

  if not found and v_email is not null then
    -- A profile without a Clerk identity (a legacy row, or a demo row)
    -- and the same e-mail address: this is the same person, so the row
    -- is adopted instead of duplicated. A row that already belongs to
    -- another Clerk account is never touched.
    select * into v_profile
    from public.profiles
    where clerk_user_id is null
      and lower(email) = lower(v_email)
    order by created_at
    limit 1;

    if found then
      update public.profiles
         set clerk_user_id = v_clerk_user_id
       where id = v_profile.id
      returning * into v_profile;
    end if;
  end if;

  if not found then
    insert into public.profiles (clerk_user_id, email, full_name, phone, avatar_url)
    values (
      v_clerk_user_id,
      v_email,
      coalesce(v_name, 'FixLink user'),
      p_phone,
      p_avatar_url
    )
    on conflict (clerk_user_id) do update
      set email = coalesce(excluded.email, public.profiles.email)
      returning * into v_profile;

    if v_profile.id is null then
      select * into v_profile
      from public.profiles
      where clerk_user_id = v_clerk_user_id;
    end if;
  else
    -- Only the editable fields are touched. role / account_status /
    -- clerk_user_id are deliberately NOT part of this update.
    update public.profiles
       set full_name = coalesce(v_name, full_name),
           phone = coalesce(p_phone, phone),
           avatar_url = coalesce(p_avatar_url, avatar_url),
           email = coalesce(v_email, email)
     where id = v_profile.id
     returning * into v_profile;
  end if;

  return v_profile;
end;
$$;

comment on function public.ensure_profile(text, text, text, text) is
  'Create or refresh the profile of the signed-in Clerk user. Idempotent. Never changes role or account_status.';

-- The grant of the previous signature is gone with the function: give it
-- to the authenticated role again, and to nobody else.
revoke all on function public.ensure_profile(text, text, text, text) from public, anon;
grant execute on function public.ensure_profile(text, text, text, text) to authenticated;

-- ---------------------------------------------------------------------
-- 4. The protected columns
-- ---------------------------------------------------------------------
-- The trigger function is deliberately NOT `security definer`: it must see
-- the role the statement really runs as, which is `service_role`,
-- `postgres` or `supabase_admin` for the trusted write paths, and
-- `authenticated` / `anon` for a direct write from the API.
create or replace function public.protect_profile_columns()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if new.role is distinct from old.role
     or new.account_status is distinct from old.account_status
     or new.clerk_user_id is distinct from old.clerk_user_id
  then
    if not public.is_admin()
       and current_user not in ('service_role', 'postgres', 'supabase_admin')
    then
      raise exception 'protected_profile_field' using errcode = '42501';
    end if;
  end if;
  return new;
end;
$$;

drop trigger if exists profiles_protect_columns on public.profiles;
create trigger profiles_protect_columns
  before update on public.profiles
  for each row execute function public.protect_profile_columns();

-- ---------------------------------------------------------------------
-- 5. Supabase Auth is no longer the identity system
-- ---------------------------------------------------------------------
-- The trigger on `auth.users` created the profile of a Supabase Auth
-- sign-up. There are no Supabase Auth sign-ups any more: the account is
-- created in Clerk, and the profile is created by `ensure_profile()` (the
-- first authenticated request) or by the Clerk webhook.
drop trigger if exists on_auth_user_created on auth.users;
drop function if exists public.handle_new_user();

-- The old column is KEPT (no table and no column of the database is
-- dropped by this migration): it is simply not the identity any more.
-- `profiles.clerk_user_id` is. The column stays for the rows that were
-- created before the switch, and it is never written any more.
do $$
begin
  if exists (
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = 'profiles'
      and column_name = 'auth_user_id'
  ) then
    execute 'comment on column public.profiles.auth_user_id is
      ''Obsolete: the identity of a profile is profiles.clerk_user_id. Kept for the rows created before the switch to Clerk; never written any more.''';
  end if;
end;
$$;

-- The column-level privileges are re-applied, so the new column is not
-- writable by the owner of the profile.
revoke update on public.profiles from anon, authenticated;
grant update (full_name, phone, avatar_url, preferred_language)
  on public.profiles to authenticated;

-- ---------------------------------------------------------------------
-- 6. The Clerk webhook
-- ---------------------------------------------------------------------
-- The webhook of Clerk tells the platform that an account was created,
-- changed or deleted. It is signed by Clerk (Svix), the route verifies
-- the signature, and the write happens with the service-role key.
--
-- These two functions are the ONLY way to write a profile without a
-- signed-in user, so they are restricted to the service role.
create or replace function public.upsert_profile_from_clerk(
  p_clerk_user_id text,
  p_email text default null,
  p_full_name text default null,
  p_avatar_url text default null
)
returns public.profiles
language plpgsql
security definer
set search_path = public
as $$
declare
  v_profile public.profiles;
  v_name text := nullif(btrim(coalesce(p_full_name, '')), '');
  v_email text := nullif(btrim(coalesce(p_email, '')), '');
begin
  if p_clerk_user_id is null or btrim(p_clerk_user_id) = '' then
    raise exception 'missing_clerk_user_id' using errcode = '22023';
  end if;

  select * into v_profile
  from public.profiles
  where clerk_user_id = p_clerk_user_id;

  if found then
    update public.profiles
       set email = coalesce(v_email, email),
           full_name = coalesce(v_name, full_name),
           avatar_url = coalesce(p_avatar_url, avatar_url)
     where id = v_profile.id
    returning * into v_profile;
  else
    insert into public.profiles (clerk_user_id, email, full_name, avatar_url)
    values (
      p_clerk_user_id,
      v_email,
      coalesce(v_name, 'FixLink user'),
      p_avatar_url
    )
    on conflict (clerk_user_id) do update
      set email = coalesce(excluded.email, public.profiles.email),
          full_name = coalesce(excluded.full_name, public.profiles.full_name),
          avatar_url = coalesce(excluded.avatar_url, public.profiles.avatar_url)
    returning * into v_profile;
  end if;

  return v_profile;
end;
$$;

comment on function public.upsert_profile_from_clerk(text, text, text, text) is
  'Create or refresh the profile of a Clerk account (the webhook of Clerk). Service role only.';

revoke all on function public.upsert_profile_from_clerk(text, text, text, text) from public, anon, authenticated;
grant execute on function public.upsert_profile_from_clerk(text, text, text, text) to service_role;

-- An account that was deleted in Clerk: the profile is closed, never
-- deleted, so the marketplace history (requests, bookings, messages)
-- survives.
create or replace function public.close_profile_of_clerk_user(
  p_clerk_user_id text
)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
  v_profile public.profiles;
begin
  if p_clerk_user_id is null or btrim(p_clerk_user_id) = '' then
    return false;
  end if;

  update public.profiles
     set account_status = 'closed'
   where clerk_user_id = p_clerk_user_id
  returning * into v_profile;

  return found;
end;
$$;

comment on function public.close_profile_of_clerk_user(text) is
  'Close the profile of a deleted Clerk account (the webhook of Clerk). Service role only.';

revoke all on function public.close_profile_of_clerk_user(text) from public, anon, authenticated;
grant execute on function public.close_profile_of_clerk_user(text) to service_role;

-- ---------------------------------------------------------------------
-- 7. The helper of the first draft of this migration
-- ---------------------------------------------------------------------
-- The identity helper was first called `clerk_user_id()`. Its name is
-- `current_clerk_user_id()` now (it matches `current_profile_id()` and
-- the other helpers), and the old name is dropped: the helpers above
-- already read the `sub` claim, so nothing depends on it any more.
drop function if exists public.clerk_user_id();


